    constexpr uint32_t kOff_UObjArr_Chunks   = 0x0010;  // Objects** (FChunkedFixedUObjectArray::Objects)
    constexpr uint32_t kOff_UObjArr_PreAlloc = 0x0018;  // PreAllocatedObjects
    constexpr uint32_t kOff_UObjArr_MaxEl    = 0x0020;  // MaxElements
