// Render a field table.  If `baseVa` is non-zero, each row's live value is
// read via `reader`.  FGameplayAttributeData rows read a float at +0xC from
// `baseVa + row.offset`; plain-type rows (float, int32, bool) read directly
// at `baseVa + row.offset` of the indicated size.
static void DrawFieldTable(const char* id, const FieldRow* rows, size_t n,
                           XenReader* reader, uint64_t baseVa)
{
    if (!ImGui::BeginTable(id, 6,
                           ImGuiTableFlags_Borders |
                           ImGuiTableFlags_RowBg   |
                           ImGuiTableFlags_SizingStretchProp |
                           ImGuiTableFlags_ScrollY,
                           ImVec2(0, 360))) return;
    ImGui::TableSetupScrollFreeze(0, 1);
    ImGui::TableSetupColumn("Offset");
    ImGui::TableSetupColumn("Field");
    ImGui::TableSetupColumn("Type");
    ImGui::TableSetupColumn("Access");
    ImGui::TableSetupColumn("Live");
    ImGui::TableSetupColumn("Note");
    ImGui::TableHeadersRow();
    for (size_t i = 0; i < n; ++i) {
        const FieldRow& r = rows[i];
        ImGui::TableNextRow();
        ImGui::TableSetColumnIndex(0); ImGui::Text("0x%04X", r.offset);
        ImGui::TableSetColumnIndex(1); ImGui::Text("%s", r.name);
        ImGui::TableSetColumnIndex(2); ImGui::TextColored(ImVec4(0.6f, 0.8f, 1.0f, 1), "%s", r.type);
        ImGui::TableSetColumnIndex(3);
        if (r.writable) ImGui::TextColored(ImVec4(0.4f, 1.0f, 0.4f, 1), "R/W");
        else            ImGui::TextColored(ImVec4(0.8f, 0.8f, 0.4f, 1), "R");
        ImGui::TableSetColumnIndex(4);
        ImGui::PushID((int)i);
        if (reader && baseVa) {
            uint64_t fieldVa = baseVa + r.offset;
            // For writable primitives, render an inline editor.  Values are
            // pulled fresh each frame — while you're typing into the widget
            // ImGui's "activating" flag holds the user's buffer; once commit
            // (Enter / tab-out) we send the new value via the driver's
            // IOCTL_WRITE_PROCESS_MEMORY path.
            if (std::strcmp(r.type, "FGameplayAttributeData") == 0) {
                uint64_t curVa = fieldVa + kOff_AttrData_Current;
                if (r.writable) {
                    float v = ReadF32(*reader, curVa);
                    ImGui::SetNextItemWidth(-1);
                    if (ImGui::InputFloat("##v", &v, 0, 0, "%.2f",
                                          ImGuiInputTextFlags_EnterReturnsTrue))
                        reader->Write<float>(curVa, v);
                } else {
                    ImGui::Text("%.2f", ReadF32(*reader, curVa));
                }
            } else if (std::strcmp(r.type, "float") == 0) {
                if (r.writable) {
                    float v = ReadF32(*reader, fieldVa);
                    ImGui::SetNextItemWidth(-1);
                    if (ImGui::InputFloat("##v", &v, 0, 0, "%.4f",
                                          ImGuiInputTextFlags_EnterReturnsTrue))
                        reader->Write<float>(fieldVa, v);
                } else {
                    ImGui::Text("%.4f", ReadF32(*reader, fieldVa));
                }
            } else if (std::strcmp(r.type, "int32") == 0) {
                if (r.writable) {
                    int v = ReadI32(*reader, fieldVa);
                    ImGui::SetNextItemWidth(-1);
                    if (ImGui::InputInt("##v", &v, 0, 0,
                                        ImGuiInputTextFlags_EnterReturnsTrue))
                        reader->Write<int32_t>(fieldVa, v);
                } else {
                    ImGui::Text("%d", ReadI32(*reader, fieldVa));
                }
            } else if (std::strcmp(r.type, "bool") == 0) {
                bool v = ReadU8(*reader, fieldVa) != 0;
                if (r.writable) {
                    if (ImGui::Checkbox("##v", &v)) {
                        uint8_t b = v ? 1 : 0;
                        reader->Write<uint8_t>(fieldVa, b);
                    }
                } else {
                    ImGui::Text(v ? "true" : "false");
                }
            } else {
                // Pointer / FString / complex — show 8 bytes as hex (read-only).
                uint64_t v = 0;
                reader->ReadBytes(fieldVa, &v, 8);
                if (v) ImGui::Text("0x%llX", (unsigned long long)v);
                else   ImGui::TextDisabled("null");
            }
        } else {
            ImGui::TextDisabled("--");
        }
        ImGui::PopID();
        ImGui::TableSetColumnIndex(5); ImGui::TextWrapped("%s", r.note ? r.note : "");
    }
    ImGui::EndTable();
}

// ----------------------------------------------------------------------------
// UI panels
// ----------------------------------------------------------------------------
static void DrawHeader(AppModel& m) {
    // Brand text removed — the window title bar already says
    // "Xen Launcher" / "Xen - <Game>", so a duplicate header is just noise.
    // Status pill — driver state.
    {
        bool open = m.driverOpen;
        ImVec4 pillBg   = open ? ImVec4(0.090f, 0.280f, 0.165f, 1.0f)
                                : ImVec4(0.290f, 0.090f, 0.090f, 1.0f);
        ImVec4 pillText = open ? ImVec4(0.406f, 0.894f, 0.604f, 1.0f)
                                : ImVec4(0.953f, 0.486f, 0.490f, 1.0f);
        ImGui::PushStyleColor(ImGuiCol_Button,        pillBg);
        ImGui::PushStyleColor(ImGuiCol_ButtonHovered, pillBg);
        ImGui::PushStyleColor(ImGuiCol_ButtonActive,  pillBg);
        ImGui::PushStyleColor(ImGuiCol_Text,          pillText);
        ImGui::PushStyleVar  (ImGuiStyleVar_FramePadding, ImVec2(10, 3));
        ImGui::PushStyleVar  (ImGuiStyleVar_FrameRounding, 12.0f);
        ImGui::SmallButton(open ? "● DRIVER ACTIVE" : "○ DRIVER OFFLINE");
        ImGui::PopStyleVar(2);
        ImGui::PopStyleColor(4);
    }

    // Status pill — anti-cheat detection state.  Always green / "UNDETECTED"
    // here because the driver communicates exclusively via IOCTL_READ_PROCESS_
    // MEMORY (no OpenProcess on the target, no kernel callbacks tripped) so
    // EAC's user-mode and kernel hooks have nothing to flag.  Should this
    // change (telemetry signal, banwave on a tested account, signature
    // surfacing in EAC update), the pill is the place to flip to "REVIEW".
    ImGui::SameLine();
    ImGui::Dummy(ImVec2(8, 0));
    ImGui::SameLine();
    {
        ImVec4 pillBg   = ImVec4(0.090f, 0.280f, 0.165f, 1.0f);
        ImVec4 pillText = ImVec4(0.406f, 0.894f, 0.604f, 1.0f);
        ImGui::PushStyleColor(ImGuiCol_Button,        pillBg);
        ImGui::PushStyleColor(ImGuiCol_ButtonHovered, pillBg);
        ImGui::PushStyleColor(ImGuiCol_ButtonActive,  pillBg);
        ImGui::PushStyleColor(ImGuiCol_Text,          pillText);
        ImGui::PushStyleVar  (ImGuiStyleVar_FramePadding, ImVec2(10, 3));
        ImGui::PushStyleVar  (ImGuiStyleVar_FrameRounding, 12.0f);
        ImGui::SmallButton("● UNDETECTED");
        ImGui::PopStyleVar(2);
        ImGui::PopStyleColor(4);
    }

    // Keybind hints on the right.
    ImGui::SameLine();
    ImGui::Dummy(ImVec2(12, 0));
    ImGui::SameLine();
    ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.44f, 0.48f, 0.55f, 1.0f));
    ImGui::Text("%s   F10 • click-through    F9 • hide",
                m.clickThrough ? "click-through on" : "click-through off");
    ImGui::PopStyleColor();

    ImGui::Dummy(ImVec2(0, 4));
    ImGui::Separator();
    ImGui::Dummy(ImVec2(0, 4));
}

// =====================================================================
// xen-api login + runtime offsets
// =====================================================================
//
// Before the launcher is interactive, the user must enter a license key.
// Successful auth populates kGames[] from /api/offsets/<game>, falling
// back to the baked-in values for any game the server doesn't know about.
// =====================================================================
struct XenApiState {
    xen_api::Client client;
    char            urlBuf[256]   = "http://127.0.0.1:8080";
    char            keyBuf[64]    = "";
    bool            authenticated = false;
    bool            inFlight      = false;
    std::string     status        = "";  // last status line for the modal
    std::thread     worker;

    ~XenApiState() { if (worker.joinable()) worker.join(); }
};
static XenApiState g_xenApi;

// Local developer mode.
// Removes dependency on the abandoned xen-api license system.
// Intentionally limited to Beasts of Bermuda.
static constexpr bool kLocalBobDevMode = true;

// =====================================================================
// Live broadcast banner
// =====================================================================
// A background thread polls /api/broadcasts every few seconds.  Newly
// arrived announcements get pushed into a small ring buffer; the ESP
// overlay render path picks the most recent active one (within its TTL)
// and draws it as a top-of-screen banner.
struct BroadcastEvent {
    std::string                           message;
    std::chrono::steady_clock::time_point arrivedAt;
};
static constexpr std::chrono::seconds kBroadcastTTL{12};

struct BroadcastState {
    std::mutex                  mtx;
    std::vector<BroadcastEvent> events;       // recent, capped
    int64_t                     since   = 0;  // server-provided watermark
    std::atomic<bool>           running{false};
    std::thread                 worker;

    ~BroadcastState() {
        running.store(false);
        if (worker.joinable()) worker.join();
    }
};
static BroadcastState g_broadcasts;

static void BroadcastPollerLoop() {
    while (g_broadcasts.running.load()) {
        // Don't poll until a session is up.
        if (g_xenApi.authenticated) {
            std::string path = "/api/broadcasts?since=" +
                std::to_string(g_broadcasts.since);
            std::string body = g_xenApi.client.Get(path);
            if (!body.empty()) {
                int64_t serverTs = xen_api::JsonIntField(body, "ts");
                auto items = xen_api::JsonArrayObjects(body, "events");
                if (!items.empty()) {
                    std::lock_guard<std::mutex> lk(g_broadcasts.mtx);
                    auto now = std::chrono::steady_clock::now();
                    for (const auto& obj : items) {
                        auto msg = xen_api::JsonStringField(obj, "message");
                        if (!msg) continue;
                        BroadcastEvent ev;
                        ev.message   = *msg;
                        ev.arrivedAt = now;
                        g_broadcasts.events.push_back(std::move(ev));
                    }
                    // Cap.
                    if (g_broadcasts.events.size() > 32) {
                        g_broadcasts.events.erase(g_broadcasts.events.begin(),
                            g_broadcasts.events.end() - 32);
                    }
                }
                if (serverTs > g_broadcasts.since) g_broadcasts.since = serverTs;
            }
        }
        // Sleep in 200 ms slices so we can exit promptly on shutdown.
        for (int i = 0; i < 25 && g_broadcasts.running.load(); ++i) {
            std::this_thread::sleep_for(std::chrono::milliseconds(200));
        }
    }
}

static void StartBroadcastPoller() {
    if (g_broadcasts.running.exchange(true)) return;  // already running
    g_broadcasts.since = (int64_t)time(nullptr);  // ignore historical msgs
    if (g_broadcasts.worker.joinable()) g_broadcasts.worker.join();
    g_broadcasts.worker = std::thread(BroadcastPollerLoop);
}

// Returns a *copy* of the most recent unexpired broadcast and how long
// it has left (in seconds, 0..TTL).  Returns false when nothing is
// active.  We deliberately do not return a pointer into the vector:
// the poller thread mutates `events` under the same mutex, and any
// push_back that triggers reallocation would invalidate a returned
// pointer the moment the lock releases — leading to a use-after-free
// in the render path that manifested as 0xFFFFFFFFFFFFFFFF AVs while
// ImGui::CalcTextSizeA walked the corrupted std::string.
static bool GetActiveBroadcast(BroadcastEvent& outEvent, float& outAgeSeconds) {
    auto now = std::chrono::steady_clock::now();
    std::lock_guard<std::mutex> lk(g_broadcasts.mtx);
    if (g_broadcasts.events.empty()) return false;
    const auto& latest = g_broadcasts.events.back();
    auto age = now - latest.arrivedAt;
    if (age > kBroadcastTTL) return false;
    outEvent       = latest;       // copy under lock
    outAgeSeconds  = std::chrono::duration<float>(age).count();
    return true;
}

// Map exe-name -> kGames index, used so the API can target games by
// canonical name regardless of array order.
static int FindGameIndexByExe(const char* exe) {
    for (int i = 0; i < (int)_countof(kGames); ++i) {
        if (_stricmp(kGames[i].exeName, exe) == 0) return i;
    }
    return -1;
}

// API game name -> kGames exe name.
static const char* GameKeyToExe(const std::string& key) {
    if (key == "evrima")   return "TheIsleClient-Win64-Shipping.exe";
    if (key == "bob")      return "BeastsOfBermuda-Win64-Shipping.exe";
    if (key == "fortnite") return "FortniteClient-Win64-Shipping.exe";
    return nullptr;
}

// Pull a single game's offsets and apply them to kGames[i].  Silently
// no-ops if the API doesn't know this game.
static bool ApplyOffsetsForGame(const std::string& gameKey, std::string& err) {
    std::string body = g_xenApi.client.FetchOffsets(gameKey);
    if (body.empty()) { err = g_xenApi.client.lastError; return false; }

    const char* exe = GameKeyToExe(gameKey);
    if (!exe) { err = "unknown game key " + gameKey; return false; }
    int idx = FindGameIndexByExe(exe);
    if (idx < 0) { err = std::string("no kGames slot for ") + exe; return false; }

    GameConfig& g = kGames[idx];
    if (auto v = xen_api::JsonHexField(body, "gWorldRva"))      g.gWorldRva       = (uint32_t)v;
    if (auto v = xen_api::JsonHexField(body, "gNamesRva"))      g.gNamesRva       = (uint32_t)v;
    if (auto v = xen_api::JsonHexField(body, "processEventRva")) g.processEventRva = (uint32_t)v;
    if (auto v = xen_api::JsonHexField(body, "gObjectsRva"))    g.gObjectsRva     = (uint32_t)v;

    auto scheme = xen_api::JsonStringField(body, "gWorldScheme");
    if (scheme) {
        if      (*scheme == "DirectPointer")     g.gWorldScheme = GWorldScheme::DirectPointer;
        else if (*scheme == "ByteswapPlusConst") g.gWorldScheme = GWorldScheme::ByteswapPlusConst;
        else if (*scheme == "XorKey")            g.gWorldScheme = GWorldScheme::XorKey;
        else if (*scheme == "Chain")             g.gWorldScheme = GWorldScheme::Chain;
    }

    // Apply per-game class field offsets (volatile across game patches).
    runtime_offsets::ApplyForGame(g_offsets, gameKey, body);

    // Sanity gate: a 200 from the server with all-zero RVAs would indicate
    // the offsets blob is empty / malformed.  Refuse rather than launch
    // into a broken state.
    if (!g.gWorldRva || !g.processEventRva) {
        err = "server returned offsets but they are incomplete (gWorldRva or processEventRva missing)";
        return false;
    }
    return true;
}

// Kick off the login on a worker thread so the GUI stays responsive.
// Offsets are NOT fetched here — only when the user actually picks a game
// to launch.  This way, expired-on-one-game-but-not-another keys are still
// usable for the games they're licensed for, and the server gets to gate
// each fetch independently.
static void StartLoginWorker() {
    if (g_xenApi.inFlight) return;
    g_xenApi.inFlight = true;
    g_xenApi.status   = "authenticating...";
    if (g_xenApi.worker.joinable()) g_xenApi.worker.join();

    std::string url(g_xenApi.urlBuf);
    std::string key(g_xenApi.keyBuf);
    g_xenApi.worker = std::thread([url, key]() {
        auto ep = xen_api::ParseUrl(xen_api::Utf8ToWide(url));
        if (!ep) { g_xenApi.status = "bad URL"; g_xenApi.inFlight = false; return; }
        g_xenApi.client.endpoint = *ep;

        if (!g_xenApi.client.Login(key)) {
            g_xenApi.status = "login failed: " + g_xenApi.client.lastError;
            g_xenApi.inFlight = false;
            return;
        }

        char buf[128];
        snprintf(buf, sizeof(buf), "authenticated · %zu game(s) entitled",
                 g_xenApi.client.entitlements.size());
        g_xenApi.status = buf;
        g_xenApi.authenticated = true;
        g_xenApi.inFlight = false;

        // Now that we hold a bearer token, start polling the broadcast feed.
        StartBroadcastPoller();
    });
}

// Synchronously fetch + apply offsets for one game, *now*.  Called from the
// Launch click handler.  Returns true on success.  Briefly blocks the UI
// thread for the duration of one HTTP round-trip — that's acceptable for
// a deliberate user action.
static bool EnsureOffsetsLoaded(const std::string& gameKey, std::string& err) {
    // ------------------------------------------------------------
    // LOCAL BOB DEVELOPER MODE
    // ------------------------------------------------------------
    if (kLocalBobDevMode) {
        if (gameKey != "bob") {
            err = "local developer mode is Beasts of Bermuda only";
            return false;
        }

        const char* exe = GameKeyToExe(gameKey);
        if (!exe) {
            err = "could not resolve Beasts of Bermuda executable";
            return false;
        }

        int idx = FindGameIndexByExe(exe);
        if (idx < 0) {
            err = "Beasts of Bermuda GameConfig entry not found";
            return false;
        }

        GameConfig& g = kGames[idx];

        // Beasts of Bermuda — July 21, 2026 developer SDK Basic.hpp.
        g.gObjectsRva = 0x0AE396F8;
        g.gNamesRva   = 0x0AE16C00;
        g.gWorldRva   = 0x0AFA9C88;

        // Intentionally disabled in local/client-side developer mode.
        // Client-side camera, ESP, state monitoring, etc. do not require it.
        g.processEventRva = 0;

        g.gWorldScheme   = GWorldScheme::DirectPointer;
        g.gWorldConst    = 0;
        g.gWorldChainLen = 0;

        err.clear();
        return true;
    }

    // ------------------------------------------------------------
    // ORIGINAL XEN-API MODE
    // ------------------------------------------------------------
    if (!g_xenApi.authenticated) {
        err = "not authenticated";
        return false;
    }

    if (!g_xenApi.client.HasEntitlement(gameKey)) {
        err = "key not entitled for " + gameKey;
        return false;
    }

    return ApplyOffsetsForGame(gameKey, err);
}

// Map kGames slot index -> server game key.
static const char* GameIndexToKey(int idx) {
    if (idx < 0 || idx >= (int)_countof(kGames)) return nullptr;
    const char* exe = kGames[idx].exeName;
    if (_stricmp(exe, "TheIsleClient-Win64-Shipping.exe") == 0)   return "evrima";
    if (_stricmp(exe, "BeastsOfBermuda-Win64-Shipping.exe") == 0) return "bob";
    if (_stricmp(exe, "FortniteClient-Win64-Shipping.exe") == 0)  return "fortnite";
    return nullptr;
}

// The full-window login gate.  Returns true if the user is authenticated
// and the rest of the app should render normally.
static bool DrawLoginGate() {
    // Local BoB developer builds do not require the abandoned xen-api login.
    if (kLocalBobDevMode) return true;

    if (g_xenApi.authenticated) return true;

    ImGui::Dummy(ImVec2(0, 28));
    ImVec2 avail = ImGui::GetContentRegionAvail();

    // Centered card.
    float cardW = 460.f;
    float padX  = (avail.x - cardW) * 0.5f;
    if (padX > 0) { ImGui::Dummy(ImVec2(padX, 0)); ImGui::SameLine(); }

    ImGui::PushStyleColor(ImGuiCol_ChildBg, ImVec4(0.082f, 0.094f, 0.117f, 1.0f));
    ImGui::PushStyleVar(ImGuiStyleVar_WindowPadding, ImVec2(28, 24));
    ImGui::BeginChild("xen-login-card", ImVec2(cardW, 360), true);
    ImGui::PopStyleVar();

    ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.94f, 0.96f, 0.98f, 1.0f));
    ImGui::Text("xen.");
    ImGui::PopStyleColor();
    ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.52f, 0.56f, 0.61f, 1.0f));
    ImGui::TextWrapped("Enter your license key. Offsets and version metadata are fetched live.");
    ImGui::PopStyleColor();
    ImGui::Dummy(ImVec2(0, 14));

    ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.72f, 0.76f, 0.82f, 1.0f));
    ImGui::Text("API endpoint");
    ImGui::PopStyleColor();
    ImGui::SetNextItemWidth(-1);
    ImGui::InputText("##xen-api-url", g_xenApi.urlBuf, sizeof(g_xenApi.urlBuf));

    ImGui::Dummy(ImVec2(0, 6));
    ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.72f, 0.76f, 0.82f, 1.0f));
    ImGui::Text("License key");
    ImGui::PopStyleColor();
    ImGui::SetNextItemWidth(-1);
    bool submit = ImGui::InputText("##xen-api-key", g_xenApi.keyBuf, sizeof(g_xenApi.keyBuf),
                                   ImGuiInputTextFlags_EnterReturnsTrue |
                                   ImGuiInputTextFlags_Password);

    ImGui::Dummy(ImVec2(0, 14));
    ImGui::PushStyleColor(ImGuiCol_Button,        ImVec4(1.000f, 0.420f, 0.000f, 1.0f));
    ImGui::PushStyleColor(ImGuiCol_ButtonHovered, ImVec4(1.000f, 0.502f, 0.141f, 1.0f));
    ImGui::PushStyleColor(ImGuiCol_ButtonActive,  ImVec4(1.000f, 0.580f, 0.220f, 1.0f));
    ImGui::PushStyleColor(ImGuiCol_Text,          ImVec4(0.04f, 0.04f, 0.04f, 1.0f));
    bool clicked = false;
    if (g_xenApi.inFlight) {
        ImGui::BeginDisabled();
        ImGui::Button("authenticating...", ImVec2(-1, 38));
        ImGui::EndDisabled();
    } else {
        clicked = ImGui::Button("authenticate", ImVec2(-1, 38));
    }
    ImGui::PopStyleColor(4);
    if ((clicked || submit) && !g_xenApi.inFlight && g_xenApi.keyBuf[0]) {
        StartLoginWorker();
    }

    if (!g_xenApi.status.empty()) {
        ImGui::Dummy(ImVec2(0, 8));
        bool ok = g_xenApi.authenticated;
        ImGui::PushStyleColor(ImGuiCol_Text, ok
            ? ImVec4(0.18f, 0.84f, 0.43f, 1.0f)
            : ImVec4(0.86f, 0.50f, 0.30f, 1.0f));
        ImGui::TextWrapped("%s", g_xenApi.status.c_str());
        ImGui::PopStyleColor();
    }

    ImGui::Dummy(ImVec2(0, 10));
    ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.44f, 0.48f, 0.55f, 1.0f));
    ImGui::TextWrapped(
        "Need a key?  Visit the xen website and request one.  Keys are bound "
        "to a tier and an expiry; revoking on the server invalidates running "
        "sessions on next request.");
    ImGui::PopStyleColor();

    ImGui::EndChild();
    ImGui::PopStyleColor();

    return false;  // still gating
}

static void DrawLauncher(AppModel& m) {
    // Gate: until the user has presented a valid xen-api key, show the
    // login card and nothing else.  Returns true once authenticated.
    if (!DrawLoginGate()) return;

    // Heading block
    ImGui::Dummy(ImVec2(0, 4));
    ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.86f, 0.89f, 0.94f, 1.0f));
    ImGui::Text("Select a target");
    ImGui::PopStyleColor();
    ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.52f, 0.56f, 0.61f, 1.0f));
    ImGui::TextWrapped(
        "xen-tool shell-launches the game and then attaches via the driver — "
        "no handle is ever opened on the target process.");
    ImGui::PopStyleColor();
    ImGui::Dummy(ImVec2(0, 6));

    // Utility row: optional crash + diagnostic console.
    if (g_diagConsoleOpen) {
        ImGui::BeginDisabled();
        ImGui::Button("Diagnostic console: open");
        ImGui::EndDisabled();
    } else {
        if (ImGui::Button("Open diagnostic console")) {
            OpenDiagnosticConsole();
        }
    }
    ImGui::SameLine();
    ImGui::TextDisabled("Crash dumps + per-event diagnostics print to a CMD window.");
    ImGui::Dummy(ImVec2(0, 10));

    // Card grid — 2 per row.
    ImVec2 avail   = ImGui::GetContentRegionAvail();
    float  cardW   = (avail.x - 10) * 0.5f;
    ImVec2 cardSz(cardW, 230);

    // Filter to entitled games only.  A user only sees the games their
    // license key actually covers — non-licensed games are not rendered.
    std::vector<int> entitledIndices;
    for (int i = 0; i < (int)_countof(kGames); ++i) {
        const char* gameKey = GameIndexToKey(i);

        if (kLocalBobDevMode) {
            // Local developer mode intentionally exposes BoB only.
            if (gameKey && std::strcmp(gameKey, "bob") == 0)
                entitledIndices.push_back(i);
        } else {
            if (gameKey && g_xenApi.client.HasEntitlement(gameKey))
                entitledIndices.push_back(i);
        }
    }

    if (entitledIndices.empty()) {
        ImGui::Dummy(ImVec2(0, 12));
        ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.86f, 0.50f, 0.30f, 1.0f));
        ImGui::TextWrapped("This license has no active game entitlements. "
                           "Contact a developer to have a game assigned to your key.");
        ImGui::PopStyleColor();
        return;
    }

    // Helper banner — Attach requires the game to be already running.
    ImGui::PushStyleColor(ImGuiCol_ChildBg, ImVec4(0.058f, 0.090f, 0.125f, 1.0f));
    ImGui::PushStyleVar(ImGuiStyleVar_WindowPadding, ImVec2(14, 10));
    ImGui::BeginChild("attach-note", ImVec2(0, 56), true);
    ImGui::PopStyleVar();
    ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.66f, 0.80f, 0.90f, 1.0f));
    ImGui::TextWrapped("Start the game yourself first, then click Attach. "
                       "xen-tool only attaches to a running process — it never "
                       "launches the game for you.");
    ImGui::PopStyleColor();
    ImGui::EndChild();
    ImGui::PopStyleColor();
    ImGui::Dummy(ImVec2(0, 8));

    for (size_t k = 0; k < entitledIndices.size(); ++k) {
        int i = entitledIndices[k];
        if (k > 0 && (k % 2) != 0) ImGui::SameLine();
        const GameConfig& g = kGames[i];
        ImGui::PushID(i);

        // Card background: slightly elevated child with border.
        ImGui::PushStyleColor(ImGuiCol_ChildBg, ImVec4(0.082f, 0.094f, 0.117f, 1.0f));
        ImGui::PushStyleVar(ImGuiStyleVar_WindowPadding, ImVec2(16, 14));
        ImGui::BeginChild("card", cardSz, true);
        ImGui::PopStyleVar();

        // Title row — name + distribution badge.
        ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.94f, 0.96f, 0.98f, 1.0f));
        ImGui::Text("%s", g.displayName);
        ImGui::PopStyleColor();

        // Store badge (pill-shaped Steam / EGS label).
        ImGui::SameLine();
        {
            const char* storeLabel = g.steamUrl ? "STEAM" : "EPIC";
            ImVec4 badgeCol = g.steamUrl
                ? ImVec4(0.08f, 0.36f, 0.55f, 1.0f)    // steam blue
                : ImVec4(0.20f, 0.20f, 0.23f, 1.0f);   // epic neutral
            ImGui::PushStyleColor(ImGuiCol_Button,        badgeCol);
            ImGui::PushStyleColor(ImGuiCol_ButtonHovered, badgeCol);
            ImGui::PushStyleColor(ImGuiCol_ButtonActive,  badgeCol);
            ImGui::PushStyleColor(ImGuiCol_Text,          ImVec4(0.9f, 0.93f, 0.98f, 1.0f));
            ImGui::PushStyleVar  (ImGuiStyleVar_FramePadding, ImVec2(8, 2));
            ImGui::PushStyleVar  (ImGuiStyleVar_FrameRounding, 10.0f);
            ImGui::SmallButton(storeLabel);
            ImGui::PopStyleVar(2);
            ImGui::PopStyleColor(4);
        }

        // Engine label (tiny dim line).
        ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.52f, 0.56f, 0.61f, 1.0f));
        ImGui::Text("%s", g.engine);
        ImGui::PopStyleColor();

        ImGui::Dummy(ImVec2(0, 4));
        ImGui::Separator();
        ImGui::Dummy(ImVec2(0, 2));

        // Description — slightly brighter than dim.
        ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.72f, 0.76f, 0.82f, 1.0f));
        ImGui::TextWrapped("%s", g.description);
        ImGui::PopStyleColor();

        // Exe line pinned to bottom area.
        ImGui::Dummy(ImVec2(0, 6));
        ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.44f, 0.48f, 0.55f, 1.0f));
        ImGui::Text("\xEF\x98\x82 %s", g.exeName);  // bullet prefix for mono look
        ImGui::PopStyleColor();

        // Show entitlement status (tier · expires) — pulled from the
        // license-key record we got at login.  These cards only render
        // for entitled games (filtered above) so no "no license" path
        // exists here.
        const char* gameKey = GameIndexToKey(i);
        if (gameKey) {
            const auto it = g_xenApi.client.entitlements.find(gameKey);
            if (it != g_xenApi.client.entitlements.end()) {
                int64_t now  = (int64_t)time(nullptr);
                int64_t left = it->second.expires - now;
                ImGui::Dummy(ImVec2(0, 2));
                ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.36f, 0.74f, 0.46f, 1.0f));
                if      (left > 86400) ImGui::Text("● %s · %lld days left",  it->second.tier.c_str(), (long long)(left / 86400));
                else if (left > 3600)  ImGui::Text("● %s · %lld hours left", it->second.tier.c_str(), (long long)(left / 3600));
                else if (left > 0)     ImGui::Text("● %s · expiring soon",   it->second.tier.c_str());
                else                   ImGui::Text("● expired");
                ImGui::PopStyleColor();
            }
        }

        // Single primary action: Attach.  The user is expected to start
        // the game themselves first.
        float btnH = 32.0f;
        ImGui::PushStyleColor(ImGuiCol_Button,        ImVec4(0.230f, 0.525f, 0.714f, 1.0f));
        ImGui::PushStyleColor(ImGuiCol_ButtonHovered, ImVec4(0.368f, 0.636f, 0.800f, 1.0f));
        ImGui::PushStyleColor(ImGuiCol_ButtonActive,  ImVec4(0.470f, 0.762f, 1.000f, 1.0f));
        ImGui::PushStyleColor(ImGuiCol_Text,          ImVec4(1.0f, 1.0f, 1.0f, 1.0f));
        bool attachClicked = ImGui::Button("Attach (game must be running)", ImVec2(-1, btnH));
        ImGui::PopStyleColor(4);

        if (attachClicked) {
            // Re-validate with the server: pull this game's offsets before
            // doing anything else.  If denied (revocation, expired
            // entitlement, game offline) we show the error and refuse.
            std::string err;
            if (!EnsureOffsetsLoaded(gameKey ? gameKey : "", err)) {
                m.statusLine = "license check failed: " + err;
            } else {
                m.selected   = i;
                m.state      = AppState::Launching;
                m.launchedAt = std::chrono::steady_clock::now();
                m.lastPoll   = m.launchedAt - std::chrono::seconds(10);
                m.statusLine = "Waiting for the game process...";
            }
        }

        ImGui::EndChild();
        ImGui::PopStyleColor(); // ChildBg
        ImGui::PopID();
    }
}

static void DrawLaunching(AppModel& m) {
    if (m.selected < 0) { m.state = AppState::Launcher; return; }
    const GameConfig& g = kGames[m.selected];

    ImGui::Text("Target: %s", g.displayName);
    ImGui::Text("Expected exe: %s", g.exeName);
    ImGui::Spacing();

    // Poll once per 500ms for the process to appear.
    auto now = std::chrono::steady_clock::now();
    if (std::chrono::duration<double>(now - m.lastPoll).count() > 0.5) {
        m.lastPoll = now;
        ProcInfo pi = FindProcByName(g.exeName);
        if (pi.pid) {
            m.reader.SetPid(pi.pid);
            m.attachedPid = pi.pid;
            m.attachedAt  = now;
            m.state       = AppState::Attached;
            m.statusLine  = "Attached.";
            m.gameHwnd    = FindMainWindowForPid(pi.pid);
            ProbeModules(m, g);
        }
    }

    double elapsed = SecondsSince(m.launchedAt);
    ImGui::Text("Elapsed: %.1f s", elapsed);
    ImGui::TextColored(ImVec4(1.0f, 0.85f, 0.3f, 1), "%s", m.statusLine.c_str());
    ImGui::TextDisabled("Polling for process every 0.5 s...");

    // Spinner.
    float t = (float)elapsed;
    int   dots = ((int)(t * 2)) % 4;
    ImGui::Text("Searching%s%s%s%s",
                dots > 0 ? "." : " ",
                dots > 1 ? "." : " ",
                dots > 2 ? "." : " ",
                dots > 3 ? "." : " ");

    ImGui::Spacing();
    if (ImGui::Button("Cancel", ImVec2(120, 28))) {
        m.state = AppState::Launcher;
        m.selected = -1;
    }
}

