static bool BobTalentIsDisabled(uint8_t talent)
{
    switch (talent) {
        case 21: // HealingRateIncrease
        case 22: // HealthPoolIncrease / Constitution
        case 28: // InjuryDamageResistance / Strong Bones
        case 56: // Aqua Affinity terrestrial
        case 57: // Aqua Affinity aquatic
            return true;
        default:
            return false;
    }
}

