static uint64_t BobTalentReadPtr(AppModel& m, uint64_t address)
{
    uint64_t p = 0;
    m.reader.ReadBytes(address, &p, sizeof(p));
    if (p < 0x10000ULL || p >= 0x00007FFF00000000ULL) return 0;
    return p;
}

static const BobPriorityTalentSpec* BobFindPriorityTalent(uint8_t talent)
{
    for (const auto& s : kBobPriorityTalents) {
        if (s.talent == talent) return &s;
    }
    return nullptr;
}


static BobTalentRowEntry* BobFindTalentRow(uint8_t talent)
{
    for (auto& e : g_bobTalentRows) {
        if (e.talent == talent) return &e;
    }
    return nullptr;
}

static float BobAcroTalentNativeMax(const BobTalentRowEntry& e)
{
    // original[]: Neg1, Val0, Val1, Val2, Val3, Val4, Val5.
    const float v5 = e.original[6];
    if (!std::isfinite(v5))
        return 1.0f;
    return std::max(1.0f, v5);
}


static float BobAcroTalentNativeValueForPoints(
    const BobTalentRowEntry& e,
    int points)
{
    points = std::clamp(points, 1, 5);

    // original[]:
    // [0] Neg1, [1] Val0, [2] Val1, [3] Val2,
    // [4] Val3, [5] Val4, [6] Val5.
    const float v =
        e.original[(size_t)points + 1];

    return std::isfinite(v)
        ? v
        : 1.0f;
}


static std::string BobTalentLower(std::string s)
{
    for (char& c : s) {
        if (c >= 'A' && c <= 'Z') c = (char)(c - 'A' + 'a');
        if (c == '_' || c == '-') c = ' ';
    }
    return s;
}

static bool BobTalentNameContains(const BobTalentRowEntry& e, const char* needle)
{
    if (!needle || !*needle) return false;
    const std::string n = BobTalentLower(needle);
    if (BobTalentLower(e.talentName).find(n) != std::string::npos) return true;
    if (BobTalentLower(e.rowKeyName).find(n) != std::string::npos) return true;
    if (const BobPriorityTalentSpec* s = BobFindPriorityTalent(e.talent)) {
        if (BobTalentLower(s->label).find(n) != std::string::npos) return true;
        if (BobTalentLower(s->enumName).find(n) != std::string::npos) return true;
    }
    return false;
}

static bool BobTalentIsAsphyxiation(const BobTalentRowEntry& e)
{
    return BobTalentNameContains(e, "asphyx");
}

static bool BobTalentIsMovementSensitive(const BobTalentRowEntry& e)
{
    // Current known movement enums.
    if (e.talent == 49 || e.talent == 50 || e.talent == 56 || e.talent == 57)
        return true;

    // New/current names are discovered from the live DataTable rather than
    // hard-coding enum values that may have moved between game builds.
    return BobTalentNameContains(e, "improved dart") ||
           BobTalentNameContains(e, "improveddart") ||
           BobTalentNameContains(e, "beach goer") ||
           BobTalentNameContains(e, "beached") ||
           BobTalentNameContains(e, "swiftness") ||
           BobTalentNameContains(e, "aqua affinity") ||
           BobTalentNameContains(e, "swim speed") ||
           BobTalentNameContains(e, "powerful legs") ||
           BobTalentNameContains(e, "powerfullegs") ||
           // Live/internal name used by the current table for Powerful Legs.
           // BobTalentLower() does not split CamelCase, so match both the
           // compact SDK-style name and human-readable variants explicitly.
           BobTalentNameContains(e, "jumpheightincrease") ||
           BobTalentNameContains(e, "jump height increase") ||
           BobTalentNameContains(e, "jumpheight") ||
           BobTalentNameContains(e, "jump height") ||
           BobTalentNameContains(e, "back up") ||
           BobTalentNameContains(e, "backup");
}

static bool BobTalentIsInterestingDynamic(const BobTalentRowEntry& e)
{
    return BobTalentIsMovementSensitive(e) ||
           BobTalentIsAsphyxiation(e) ||
           BobTalentNameContains(e, "dart") ||
           BobTalentNameContains(e, "beach") ||
           BobTalentNameContains(e, "roar") ||
           BobTalentNameContains(e, "voracious");
}

static void BobClearTalentPipelineDiagnostics();

static void BobClearTalentCache()
{
    g_bobTalentRows.clear();
    g_bobTalentTable = 0;
    g_bobTalentWorld = 0;
    g_bobTalentLastEquivalent = 1.0f;
    g_bobTalentModified = false;
    g_bobAcroTalent = BobAcroTalentState{};
    g_bobAcroServerProbe = BobAcroServerProbeState{};
    g_bobAcroServerProbe = BobAcroServerProbeState{};
    g_bobTalentNativeReferenceTrusted = false;
    g_bobTalentNativeReferenceWhy = "not captured";
    g_bobTalentCustomInitialized = false;
    g_bobTalentCustomDirty.fill(false);
    BobClearTalentPipelineDiagnostics();
}

// Sample the ORIGINAL positive talent curve at a fractional level 1..10.
//
// BoB's table only stores Val1..Val5. Levels 6..10 therefore continue the
// final vanilla step (Val4 -> Val5) linearly. This is especially useful for
// Swiftness:
//   current vanilla Val4=1.143, Val5=1.182
//   extrapolated level 7 ~= 1.260
// while the old known-working PAK used 1.25.
static float BobSampleOriginalTalentCurve(const BobTalentRowEntry& e, float level)
{
    level = std::clamp(level, 1.0f, 10.0f);

    // original[] indexes:
    // 0 Neg1, 1 Val0, 2 Val1, 3 Val2, 4 Val3, 5 Val4, 6 Val5.
    if (level <= 5.0f) {
        const int loLevel = (int)std::floor(level);
        const int hiLevel = std::min(5, loLevel + 1);
        const float t = level - (float)loLevel;

        const float a = e.original[(size_t)(loLevel + 1)];
        const float b = e.original[(size_t)(hiLevel + 1)];
        return a + (b - a) * t;
    }

    const float v4 = e.original[5];
    const float v5 = e.original[6];
    const float lastStep = v5 - v4;
    float out = v5 + (level - 5.0f) * lastStep;

    // Most BoB talent modifiers are non-negative multipliers/amounts. Avoid
    // extrapolating an inverse curve through zero. Weather Resistance has its
    // own explicit 0.10 override below.
    if (e.original[1] >= 0.0f && v4 >= 0.0f && v5 >= 0.0f)
        out = std::max(0.01f, out);

    return out;
}


static void BobEnsureTalentCustomSliders()
{
    if (g_bobTalentCustomInitialized) return;

    g_bobTalentCustomModifier.fill(1.0f);
    g_bobTalentCustomDirty.fill(false);

    // Seed each user-facing control from its captured one-point value purely
    // for display. It is NOT written until that slider is changed.
    for (const auto& row : g_bobTalentRows) {
        // Seed every enum slot. Coupled controls later read the leader slot
        // (2/49/56/61), whose own row is present in the captured table.
        float seed = row.original[2];
        if (!std::isfinite(seed)) seed = 1.0f;

        if (row.talent == 73) {
            g_bobTalentCustomModifier[(size_t)row.talent] =
                std::clamp(seed, 1.0f, BobAcroTalentNativeMax(row));
        } else {
            g_bobTalentCustomModifier[(size_t)row.talent] =
                std::clamp(seed, kBobTalentTypedMin, kBobTalentTypedMax);
        }
    }

    g_bobTalentCustomInitialized = true;
}

static bool BobTalentPositiveCurveIsFlat(const BobTalentRowEntry& e)
{
    float lo = e.original[2];
    float hi = e.original[2];
    for (size_t i = 3; i <= 6; ++i) {
        lo = std::min(lo, e.original[i]);
        hi = std::max(hi, e.original[i]);
    }
    const float scale = std::max(1.0f, std::max(std::fabs(lo), std::fabs(hi)));
    return std::fabs(hi - lo) <= 0.0005f * scale;
}

static bool BobTalentOriginalAllNear(const BobTalentRowEntry& e,
                                     float value, float tol)
{
    for (size_t i = 2; i <= 6; ++i) {
        if (!std::isfinite(e.original[i]) ||
            std::fabs(e.original[i] - value) > tol)
            return false;
    }
    return true;
}

enum class BobTalentBaselineHealth : uint8_t {
    Progressive,
    LegitFlatOrUnknown,
    KnownModifiedSignature
};

static BobTalentBaselineHealth BobGetTalentBaselineHealth(
    const BobTalentRowEntry& e, std::string* why = nullptr)
{
    if (!BobTalentPositiveCurveIsFlat(e)) {
        if (why) *why = "progressive captured curve";
        return BobTalentBaselineHealth::Progressive;
    }

    // These exact flat signatures are already present in the user's uploaded
    // historical PAK evidence. If Xen captures one of them as "original", the
    // point slider has mathematically lost the vanilla curve and cannot infer
    // 1/2/3/4/5-point values from that session.
    if (e.talent == 6 && BobTalentOriginalAllNear(e, 1.33f, 0.0025f)) {
        if (why) *why =
            "Brawler captured as flat 1.33 (matches old Talents.pak signature)";
        return BobTalentBaselineHealth::KnownModifiedSignature;
    }
    if (e.talent == 102 && BobTalentOriginalAllNear(e, 10.0f, 0.001f)) {
        if (why) *why =
            "Forager captured as flat 10.0 (matches talent10xfor.pak signature)";
        return BobTalentBaselineHealth::KnownModifiedSignature;
    }
    if (e.talent == 4 && BobTalentOriginalAllNear(e, 10.0f, 0.001f)) {
        if (why) *why =
            "Strong Lungs captured as flat 10.0 (legacy modified signature)";
        return BobTalentBaselineHealth::KnownModifiedSignature;
    }
    if (e.talent == 49 && BobTalentOriginalAllNear(e, 1.25f, 0.0025f)) {
        if (why) *why =
            "Swiftness captured as flat 1.25 (old Talents.pak signature)";
        return BobTalentBaselineHealth::KnownModifiedSignature;
    }
    if (e.talent == 50 && BobTalentOriginalAllNear(e, 1.325f, 0.003f)) {
        if (why) *why =
            "Swiftness-ground captured as flat 1.325 (legacy signature)";
        return BobTalentBaselineHealth::KnownModifiedSignature;
    }

    if (why) *why =
        "flat captured curve; point-by-point scaling is not present in TalentInfoData";
    return BobTalentBaselineHealth::LegitFlatOrUnknown;
}

static const char* BobTalentBaselineHealthShort(const BobTalentRowEntry& e)
{
    switch (BobGetTalentBaselineHealth(e, nullptr)) {
        case BobTalentBaselineHealth::Progressive:
            return "CURVE OK";
        case BobTalentBaselineHealth::KnownModifiedSignature:
            return "MODIFIED BASELINE";
        default:
            return "FLAT CURVE";
    }
}

