static std::string BobTalentUiName(const BobTalentRowEntry& e)
{
    // Current internal enum/TalentName is TenaciousRoar, while the user-facing
    // talent is Voracious Roar.
    if (e.talent == 118 || BobTalentNameContains(e, "tenacious roar") ||
        BobTalentNameContains(e, "tenaciousroar")) {
        return "Voracious Roar (TenaciousRoar)";
    }

    if (const BobPriorityTalentSpec* spec = BobFindPriorityTalent(e.talent))
        return spec->label;

    if (!e.talentName.empty() && e.talentName != "None")
        return e.talentName;
    if (!e.rowKeyName.empty() && e.rowKeyName != "None")
        return e.rowKeyName;

    char b[32];
    std::snprintf(b, sizeof(b), "Talent %u", (unsigned)e.talent);
    return b;
}

// Known user-facing talents that are split across multiple internal modifier
// rows in the current SDK/DataTable. We merge ONLY pairs that are supported by
// the live names/SDK evidence instead of guessing from coincidentally equal
// values.
static uint8_t BobTalentControlLeader(uint8_t talent)
{
    switch (talent) {
        case 3:  return 2;   // Beach Goer: comfort + beached mobility
        case 50: return 49;  // Swiftness: normal + flyer-ground
        case 57: return 56;  // Aqua Affinity: terrestrial + aquatic
        case 62: return 61;  // Nimble Footed: normal + flyer-ground
        default: return talent;
    }
}

static const char* BobTalentKnownGroupLabel(uint8_t leader)
{
    switch (leader) {
        case 2:  return "Beach Goer";
        case 49: return "Swiftness";
        case 56: return "Aqua Affinity";
        case 61: return "Nimble Footed";
        default: return nullptr;
    }
}

static bool BobTalentRowBelongsToControl(const BobTalentRowEntry& row,
                                         uint8_t leader)
{
    return BobTalentControlLeader(row.talent) == leader;
}

static bool BobTalentControlHasMovementSensitive(uint8_t leader)
{
    for (const auto& row : g_bobTalentRows)
        if (BobTalentRowBelongsToControl(row, leader) &&
            BobTalentIsMovementSensitive(row)) return true;
    return false;
}

static bool BobTalentControlHasLegacyProtected(uint8_t leader)
{
    for (const auto& row : g_bobTalentRows)
        if (BobTalentRowBelongsToControl(row, leader) &&
            BobTalentIsDisabled(row.talent)) return true;
    return false;
}

static bool BobTalentControlHasFlatCurve(uint8_t leader)
{
    for (const auto& row : g_bobTalentRows)
        if (BobTalentRowBelongsToControl(row, leader) &&
            BobTalentPositiveCurveIsFlat(row)) return true;
    return false;
}

static bool BobTalentControlHasAsphyxiation(uint8_t leader)
{
    for (const auto& row : g_bobTalentRows)
        if (BobTalentRowBelongsToControl(row, leader) &&
            BobTalentIsAsphyxiation(row)) return true;
    return false;
}

// Hybrid AE: identifies rows with known bad/unstable runtime propagation.
// These are MANUAL-ONLY: individual slider/text edits are still allowed, but
// the native 5/3 bulk preset neutralizes them to 1.0 instead of boosting them.
static bool BobTalentControlIsRuntimeUnsafe(uint8_t leader)
{
    return BobTalentControlHasMovementSensitive(leader) ||
           BobTalentControlHasLegacyProtected(leader);
}

// Back Up is also disabled from runtime talent modification.
// The exact enum can vary across table/build revisions, so identify it from
// the captured live TalentInfo row name instead of hard-coding an enum.
static bool BobTalentControlHasBackUp(uint8_t leader)
{
    for (const auto& row : g_bobTalentRows) {
        if (!BobTalentRowBelongsToControl(row, leader))
            continue;

        if (BobTalentNameContains(row, "back up") ||
            BobTalentNameContains(row, "backup")) {
            return true;
        }
    }

    return false;
}

// Controls in this category remain visible for diagnostics/native-value
// reference, but Xen must never write their TalentInfo rows, mark them dirty
// through bulk presets, or send their local SetX refreshes.
static bool BobTalentControlIsDisplayOnly(uint8_t leader)
{
    return leader == 49 ||
           BobTalentControlHasBackUp(leader);
}

// AH15.10: Swiftness is no longer a local TalentInfo/SetX target.
// The completed A/B tests showed that a legitimate server-recognized
// 3-points/+2-inherit creature and a locally forged 3/+2 record both resolve
// GetTalentMod(49)=1.182, but only the legitimate inherited creature remains
// authoritative/stable. Xen therefore treats the Swiftness control as
// REAL-INHERIT DISPLAY ONLY.
static bool BobTalentControlIsRealInheritOnly(uint8_t leader)
{
    return leader == 49;
}

static std::string BobTalentControlName(const BobTalentRowEntry& leaderRow)
{
    if (const char* grouped = BobTalentKnownGroupLabel(leaderRow.talent))
        return grouped;
    return BobTalentUiName(leaderRow);
}

static std::string BobTalentControlMembers(uint8_t leader)
{
    std::string out;
    for (const auto& row : g_bobTalentRows) {
        if (!BobTalentRowBelongsToControl(row, leader)) continue;
        if (!out.empty()) out += " + ";
        char b[32];
        std::snprintf(b, sizeof(b), "%u:", (unsigned)row.talent);
        out += b;
        out += !row.talentName.empty() ? row.talentName : row.rowKeyName;
    }
    return out;
}

static std::string BobTalentControlPointValues(uint8_t leader, int points)
{
    if (!g_bobTalentNativeReferenceTrusted) return "UNTRUSTED";
    // Display-only reference to the captured native curve. Hybrid X's slider
    // itself is an exact raw modifier, not a point-equivalent selector.
    std::string out;
    for (const auto& row : g_bobTalentRows) {
        if (!BobTalentRowBelongsToControl(row, leader)) continue;
        int p = std::clamp(points, 1, 5);
        const float v = row.original[(size_t)p + 1];
        char b[48];
        std::snprintf(b, sizeof(b), "%s%.4g", out.empty() ? "" : " / ", v);
        out += b;
    }
    return out.empty() ? "-" : out;
}

static bool BobTalentCapturedCurveIsFlat(const BobTalentRowEntry& e)
{
    const float v = e.original[2];
    for (size_t i = 3; i <= 6; ++i) {
        const float x = e.original[i];
        if (!std::isfinite(x) || std::fabs(x - v) > 0.0005f)
            return false;
    }
    return true;
}

static bool BobValidateNativeTalentReference(std::string& why)
{
    // These are long-established progressive modifier rows in the current BoB
    // TalentInfo layout. We deliberately do NOT hard-code their numeric values
    // as the displayed native values; they are used only as contamination
    // sentinels. A previous Xen exact-target write flattens Val1..Val5, so if
    // several of these normally-progressive rows are flat, the table is not a
    // trustworthy native baseline.
    constexpr uint8_t kProgressiveSentinels[] = { 0, 21, 22, 29, 53 };
    int found = 0;
    int flat = 0;
    int extreme = 0;
    std::string details;

    for (uint8_t t : kProgressiveSentinels) {
        const BobTalentRowEntry* e = nullptr;
        for (const auto& r : g_bobTalentRows) {
            if (r.talent == t) { e = &r; break; }
        }
        if (!e) continue;
        ++found;
        if (BobTalentCapturedCurveIsFlat(*e)) {
            ++flat;
            if (!details.empty()) details += ", ";
            details += BobTalentUiName(*e) + " flat";
        }
        for (size_t i = 2; i <= 6; ++i) {
            if (std::fabs(e->original[i]) >= 5.0f) {
                ++extreme;
                if (!details.empty()) details += ", ";
                details += BobTalentUiName(*e) + " extreme";
                break;
            }
        }
    }

    if (found >= 3 && (flat >= 2 || extreme > 0)) {
        why = "captured table looks modified: " + details +
              ". Fully restart Beasts of Bermuda, do not apply talents, then Capture once.";
        return false;
    }

    why = "clean baseline sanity check passed";
    return true;
}

static bool BobWriteCapturedZeroAndPositiveRow(AppModel& m,
                                                 BobTalentRowEntry& e)
{
    // Val0..Val5 are contiguous. Neg1Val is deliberately untouched here.
    float originalValues[6] = {
        e.original[1], e.original[2], e.original[3], e.original[4],
        e.original[5], e.original[6]
    };
    const size_t bytes = sizeof(originalValues);
    if (m.reader.WriteBytes(e.row + kBobOff_TalentRow_Val0,
                            originalValues, bytes) != bytes)
        return false;

    for (int i = 0; i < 6; ++i)
        e.live[(size_t)i + 1] = originalValues[i];
    return true;
}

static bool BobCaptureTalentRows(AppModel& m, std::string& status)
{
    if (!m.bob.gameInstance) {
        status = "BoB GameInstance unresolved";
        return false;
    }

    uint64_t table = BobTalentReadPtr(
        m, m.bob.gameInstance + kBobOff_GI_TalentInfoTable);
    if (!table) {
        status = "TalentInfoDataTableRef (+0x210) is null";
        return false;
    }

    // Preserve the first capture from this exact live DataTable so Restore
    // always means the pre-Xen values.
    if (table == g_bobTalentTable && !g_bobTalentRows.empty()) {
        char b[160];
        std::snprintf(b, sizeof(b), "Using %zu cached TalentInfo rows",
                      g_bobTalentRows.size());
        BobEnsureTalentCustomSliders();
        status = b;
        return true;
    }

    // A changed table/world means a new session/load.  Do not carry stale row
    // pointers across it.
    g_bobTalentRows.clear();
    g_bobTalentTable = table;
    g_bobTalentWorld = m.bob.gWorld;
    g_bobTalentLastEquivalent = 1.0f;
    g_bobTalentModified = false;
    g_bobAcroTalent = BobAcroTalentState{};

    // UE4 TMap<FName,uint8*> RowMap.  Same TMap/TSet layout already used by
    // Xen for BoB OnlinePlayersMap and PlayerGroupsMap:
    //   +0x00 elementsData
    //   +0x08 elementsNum/elementsMax
    //   +0x10 inline allocation flags [4]
    //   +0x20 heap allocation flags ptr
    //   +0x28 numBits
    // Each TSetElement<TPair<FName,uint8*>> is:
    //   FName key 8 + row ptr 8 + hash next/index 8 = 24 bytes.
    const uint64_t mapAddr = table + kBobOff_DataTable_RowMap;
    uint8_t hdr[0x30] = {};
    if (m.reader.ReadBytes(mapAddr, hdr, sizeof(hdr)) != sizeof(hdr)) {
        status = "Could not read UDataTable::RowMap header";
        BobClearTalentCache();
        return false;
    }

    uint64_t elementsData = 0;
    int32_t elementsNum = 0;
    uint32_t inlineFlags[4] = {};
    uint64_t secondaryFlags = 0;
    int32_t numBits = 0;

    std::memcpy(&elementsData,   hdr + 0x00, 8);
    std::memcpy(&elementsNum,    hdr + 0x08, 4);
    std::memcpy(inlineFlags,     hdr + 0x10, 16);
    std::memcpy(&secondaryFlags, hdr + 0x20, 8);
    std::memcpy(&numBits,        hdr + 0x28, 4);

    if (!elementsData || elementsNum <= 0 ||
        numBits <= 0 || numBits > 2048) {
        char b[220];
        std::snprintf(b, sizeof(b),
                      "Talent RowMap implausible: data=%llX num=%d bits=%d",
                      (unsigned long long)elementsData,
                      elementsNum, numBits);
        status = b;
        BobClearTalentCache();
        return false;
    }

    constexpr size_t kStride = 24;
    std::vector<uint8_t> bulk((size_t)numBits * kStride, 0);
    if (m.reader.ReadBytes(elementsData, bulk.data(), bulk.size())
        != bulk.size()) {
        status = "Could not read Talent RowMap elements";
        BobClearTalentCache();
        return false;
    }

    std::vector<uint32_t> heapFlags;
    if (numBits > 128 && secondaryFlags) {
        heapFlags.resize(((size_t)numBits + 31) / 32, 0);
        m.reader.ReadBytes(secondaryFlags, heapFlags.data(),
                           heapFlags.size() * sizeof(uint32_t));
    }

    int allocated = 0;
    int rejected = 0;
    std::unordered_set<uint32_t> seenTalents;

    uint64_t fnp = 0;
    if (m.mainBase && m.selected >= 0 &&
        m.selected < (int)_countof(kGames) && kGames[m.selected].gNamesRva) {
        fnp = m.mainBase + kGames[m.selected].gNamesRva;
    }

    for (int32_t i = 0; i < numBits; ++i) {
        uint32_t word = (numBits <= 128)
            ? inlineFlags[i / 32]
            : (i / 32 < (int32_t)heapFlags.size()
                ? heapFlags[(size_t)i / 32] : 0);
        if (!((word >> (i & 31)) & 1)) continue;
        ++allocated;

        const uint8_t* slot = bulk.data() + (size_t)i * kStride;
        uint64_t row = 0;
        std::memcpy(&row, slot + 8, 8);

        if (row < 0x10000ULL || row >= 0x00007FFF00000000ULL) {
            ++rejected;
            continue;
        }

        uint8_t talent = 0xFF;
        if (m.reader.ReadBytes(row + kBobOff_TalentRow_Talent,
                               &talent, sizeof(talent)) != sizeof(talent)) {
            ++rejected;
            continue;
        }

        // ETalentEnum::None == 133; current real rows are 0..132.
        if (talent > 132 || seenTalents.find(talent) != seenTalents.end()) {
            ++rejected;
            continue;
        }

        std::array<float, 7> vals{};
        if (m.reader.ReadBytes(row + kBobOff_TalentRow_Neg1,
                               vals.data(),
                               vals.size() * sizeof(float))
            != vals.size() * sizeof(float)) {
            ++rejected;
            continue;
        }

        bool plausible = true;
        for (float v : vals) {
            if (!std::isfinite(v) || std::fabs(v) > 100000.0f) {
                plausible = false;
                break;
            }
        }
        if (!plausible) {
            ++rejected;
            continue;
        }

        BobTalentRowEntry e;
        e.talent = talent;
        e.row = row;

        if (fnp) {
            uint32_t rowKeyFn = 0;
            std::memcpy(&rowKeyFn, slot + 0, sizeof(rowKeyFn));
            e.rowKeyName = BobResolveFName(m.reader, fnp, rowKeyFn);

            uint32_t talentNameFn = 0;
            if (m.reader.ReadBytes(row + kBobOff_TalentRow_TalentName,
                                   &talentNameFn, sizeof(talentNameFn))
                == sizeof(talentNameFn)) {
                e.talentName = BobResolveFName(m.reader, fnp, talentNameFn);
            }
        }

        e.original = vals;
        e.live = vals;
        g_bobTalentRows.push_back(e);
        seenTalents.insert(talent);
    }

    std::sort(g_bobTalentRows.begin(), g_bobTalentRows.end(),
              [](const BobTalentRowEntry& a, const BobTalentRowEntry& b) {
                  return a.talent < b.talent;
              });

    if (g_bobTalentRows.empty()) {
        char b[220];
        std::snprintf(b, sizeof(b),
                      "Talent table found, but no FTalentData rows validated "
                      "(allocated=%d rejected=%d)",
                      allocated, rejected);
        status = b;
        BobClearTalentCache();
        return false;
    }

    g_bobTalentNativeReferenceTrusted =
        BobValidateNativeTalentReference(g_bobTalentNativeReferenceWhy);

    char b[420];
    std::snprintf(b, sizeof(b),
                  "Captured %zu TalentInfo rows from table 0x%llX "
                  "(map num=%d allocated=%d rejected=%d)",
                  g_bobTalentRows.size(),
                  (unsigned long long)g_bobTalentTable,
                  elementsNum, allocated, rejected);
    BobEnsureTalentCustomSliders();
    status = b;
    status += g_bobTalentNativeReferenceTrusted
        ? " | native reference: TRUSTED"
        : " | native reference: UNTRUSTED - " + g_bobTalentNativeReferenceWhy;
    return true;
}

static uint64_t BobGetTalentComponent(AppModel& m)
{
    if (!m.bob.pawn) return 0;
    return BobTalentReadPtr(m, m.bob.pawn + kBobOff_BC_CompTalents);
}

static bool BobRebuildCurrentTalentMap(AppModel& m, const GameConfig& g,
                                       std::string& status)
{
    uint64_t comp = BobGetTalentComponent(m);
    if (!comp) {
        status = "Current pawn Comp_Talents (+0x6F0) is null";
        return false;
    }

    std::vector<uint8_t> parms; // OnRep_SetTalentLevels() has no parameters
    std::vector<std::pair<size_t, FStringArg>> noFx;
    std::string invokeStatus;

    if (!InvokeRpc(m, g, comp, { "Comp_Talents" },
                   "OnRep_SetTalentLevels", parms, noFx, invokeStatus)) {
        status = invokeStatus;
        return false;
    }

    status = "Rebuilt current Comp_Talents TalentMap from patched TalentInfoData";
    return true;
}

static bool BobGetCurrentTalentMod(AppModel& m, const GameConfig& g,
                                   uint8_t talent, float& outMod,
                                   std::string& status)
{
    uint64_t comp = BobGetTalentComponent(m);
    if (!comp) {
        status = "Current pawn Comp_Talents is null";
        return false;
    }

    // Comp_Talents_GetTalentMod params:
    //   +0x00 ETalentEnum Talent
    //   +0x01 pad[3]
    //   +0x04 float ReturnValue
    // total 0x08
    std::vector<uint8_t> parms(8, 0);
    parms[0] = talent;

    std::vector<uint8_t> readback;
    std::vector<std::pair<size_t, FStringArg>> noFx;
    std::string invokeStatus;
    if (!InvokeRpc(m, g, comp, { "Comp_Talents" },
                   "GetTalentMod", parms, noFx, invokeStatus,
                   0, &readback)) {
        status = invokeStatus;
        return false;
    }

    if (readback.size() < 8) {
        status = "GetTalentMod returned a short parameter buffer";
        return false;
    }

    float value = 0.0f;
    std::memcpy(&value, readback.data() + 4, 4);
    if (!std::isfinite(value) || std::fabs(value) > 100000.0f) {
        status = "GetTalentMod returned an implausible value";
        return false;
    }

    outMod = value;
    return true;
}

struct BobTalentLevelRecord {
    uint8_t talent = 0;
    int32_t points = 0;
    int32_t inherited = 0;
    float overrideValue = 0.0f;
    int32_t purchased = 0;
};

static bool BobReadTalentLevelRecords(AppModel& m,
                                      std::vector<BobTalentLevelRecord>& out,
                                      std::string& status)
{
    out.clear();
    uint64_t comp = BobGetTalentComponent(m);
    if (!comp) {
        status = "Current pawn Comp_Talents is null";
        return false;
    }

    const uint64_t arrAddr =
        comp + kBobOff_CompTalents_CharacterLevels + kBobOff_TalentsToRep_Items;

    uint8_t hdr[16] = {};
    if (m.reader.ReadBytes(arrAddr, hdr, sizeof(hdr)) != sizeof(hdr)) {
        status = "Could not read CharacterTalentLevels.Items";
        return false;
    }

    uint64_t data = 0;
    int32_t num = 0, maxN = 0;
    std::memcpy(&data, hdr + 0, 8);
    std::memcpy(&num,  hdr + 8, 4);
    std::memcpy(&maxN, hdr + 12, 4);

    if (num < 0 || num > 256 || maxN < num || maxN > 512) {
        status = "CharacterTalentLevels.Items header is implausible";
        return false;
    }
    if (num == 0) {
        status = "Current creature has no FTalentLevel records";
        return true;
    }
    if (!data) {
        status = "CharacterTalentLevels.Items data is null";
        return false;
    }

    std::vector<uint8_t> items((size_t)num * kBobSize_FTalentLevel, 0);
    if (m.reader.ReadBytes(data, items.data(), items.size()) != items.size()) {
        status = "Could not read FTalentLevel array";
        return false;
    }

    out.reserve((size_t)num);
    for (int32_t i = 0; i < num; ++i) {
        const uint8_t* p = items.data() + (size_t)i * kBobSize_FTalentLevel;

        BobTalentLevelRecord r;
        r.talent = p[kBobOff_TalentLevel_Talent];
        std::memcpy(&r.points,        p + kBobOff_TalentLevel_Points,    4);
        std::memcpy(&r.inherited,     p + kBobOff_TalentLevel_Inherited, 4);
        std::memcpy(&r.overrideValue, p + kBobOff_TalentLevel_Override,  4);
        std::memcpy(&r.purchased,     p + kBobOff_TalentLevel_Purchased, 4);

        if (r.talent <= 132)
            out.push_back(r);
    }

    char b[160];
    std::snprintf(b, sizeof(b),
                  "Read %zu FTalentLevel records (read-only)", out.size());
    status = b;
    return true;
}


// ============================================================================
// Hybrid AH15.8 - LOCAL-ONLY Swiftness inherit test.
//
// This intentionally does NOT edit TalentInfoData and does NOT call any
// SERVER_ talent function. It changes only the current pawn's local
// FTalentLevel::Inherited field for enum 49 (SpeedIncrease), rebuilds the
// local Comp_Talents TalentMap through OnRep_SetTalentLevels(), then reads
// GetTalentMod(49) and MovementSpeedMod for diagnosis.
//
// Only +1 and +2 are exposed because the immediate goal is to reproduce the
// old "real positive inherit" behavior without guessing arbitrary values.
// ============================================================================

struct BobSwiftnessInheritTestState {
    uint64_t pawn = 0;
    uint64_t recordAddr = 0;
    bool captured = false;

    int32_t originalPoints = 0;
    int32_t currentPoints = 0;
    int32_t originalInherited = 0;
    int32_t currentInherited = 0;
    int32_t purchased = 0;
    float overrideValue = 0.0f;

    bool getModOk = false;
    float getMod = 0.0f;

    bool movementOk = false;
    float movementSpeedMod = 0.0f;

    std::string status = "Not captured";
};

static BobSwiftnessInheritTestState g_bobSwiftInheritTest;

static bool BobFindTalentLevelRecordAddress(
    AppModel& m,
    uint8_t talent,
    uint64_t& outAddr,
    BobTalentLevelRecord& outRecord,
    std::string& status)
{
    outAddr = 0;
    outRecord = BobTalentLevelRecord{};

    uint64_t comp = BobGetTalentComponent(m);
    if (!comp) {
        status = "Current pawn Comp_Talents is null";
        return false;
    }

    const uint64_t arrAddr =
        comp +
        kBobOff_CompTalents_CharacterLevels +
        kBobOff_TalentsToRep_Items;

    uint8_t hdr[16] = {};
    if (m.reader.ReadBytes(
            arrAddr,
            hdr,
            sizeof(hdr)) != sizeof(hdr)) {
        status = "Could not read CharacterTalentLevels.Items";
        return false;
    }

    uint64_t data = 0;
    int32_t num = 0;
    int32_t maxN = 0;

    std::memcpy(&data, hdr + 0, 8);
    std::memcpy(&num,  hdr + 8, 4);
    std::memcpy(&maxN, hdr + 12, 4);

    if (!data ||
        num <= 0 ||
        num > 256 ||
        maxN < num ||
        maxN > 512) {
        status = "Talent array header is unavailable/implausible";
        return false;
    }

    for (int32_t i = 0; i < num; ++i) {
        const uint64_t p =
            data +
            (uint64_t)i *
            kBobSize_FTalentLevel;

        uint8_t t = 0;
        if (m.reader.ReadBytes(
                p + kBobOff_TalentLevel_Talent,
                &t,
                1) != 1) {
            continue;
        }

        if (t != talent)
            continue;

        BobTalentLevelRecord r;
        r.talent = t;

        m.reader.ReadBytes(
            p + kBobOff_TalentLevel_Points,
            &r.points,
            4);

        m.reader.ReadBytes(
            p + kBobOff_TalentLevel_Inherited,
            &r.inherited,
            4);

        m.reader.ReadBytes(
            p + kBobOff_TalentLevel_Override,
            &r.overrideValue,
            4);

        m.reader.ReadBytes(
            p + kBobOff_TalentLevel_Purchased,
            &r.purchased,
            4);

        outAddr = p;
        outRecord = r;

        char b[96];
        std::snprintf(
            b,
            sizeof(b),
            "Found enum %u FTalentLevel",
            (unsigned)talent);
        status = b;
        return true;
    }

    char b[96];
    std::snprintf(
        b,
        sizeof(b),
        "Talent enum %u FTalentLevel record not found",
        (unsigned)talent);
    status = b;
    return false;
}

static void BobRefreshSwiftnessInheritTestReadback(
    AppModel& m,
    const GameConfig& g)
{
    auto& st = g_bobSwiftInheritTest;

    if (!st.captured ||
        st.pawn != m.bob.pawn) {
        return;
    }

    BobTalentLevelRecord r;
    uint64_t addr = 0;
    std::string findStatus;

    if (BobFindTalentLevelRecordAddress(
            m,
            49,
            addr,
            r,
            findStatus)) {
        st.recordAddr = addr;
        st.currentInherited = r.inherited;
        st.currentPoints = r.points;
        st.overrideValue = r.overrideValue;
        st.purchased = r.purchased;
    }

    std::string modStatus;
    st.getModOk =
        BobGetCurrentTalentMod(
            m,
            g,
            49,
            st.getMod,
            modStatus);

    float movement = 0.0f;
    const bool movementReadOk =
        m.reader.ReadBytes(
            m.bob.pawn +
                kBobOff_BC_MovementSpeedMod,
            &movement,
            sizeof(movement)) ==
        sizeof(movement);

    st.movementOk =
        movementReadOk &&
        std::isfinite(movement) &&
        std::fabs(movement) <
            100000.0f;

    if (st.movementOk)
        st.movementSpeedMod = movement;
}

static bool BobCaptureSwiftnessInheritBaseline(
    AppModel& m,
    const GameConfig& g,
    std::string& status)
{
    BobTalentLevelRecord r;
    uint64_t addr = 0;

    if (!BobFindTalentLevelRecordAddress(
            m,
            49,
            addr,
            r,
            status)) {
        return false;
    }

    auto& st = g_bobSwiftInheritTest;
    st = BobSwiftnessInheritTestState{};

    st.pawn = m.bob.pawn;
    st.recordAddr = addr;
    st.captured = true;

    st.originalPoints = r.points;
    st.currentPoints = r.points;
    st.originalInherited = r.inherited;
    st.currentInherited = r.inherited;
    st.overrideValue = r.overrideValue;
    st.purchased = r.purchased;

    BobRefreshSwiftnessInheritTestReadback(
        m,
        g);

    char b[256];
    std::snprintf(
        b,
        sizeof(b),
        "Captured Swiftness baseline: Points=%d Inherited=%+d GetTalentMod=%s%.6g Movement=%s%.6g",
        st.originalPoints,
        st.originalInherited,
        st.getModOk ? "" : "? ",
        st.getMod,
        st.movementOk ? "" : "? ",
        st.movementSpeedMod);

    st.status = b;
    status = b;
    return true;
}

static bool BobApplyLocalSwiftnessInherited(
    AppModel& m,
    const GameConfig& g,
    int32_t inherited,
    std::string& status)
{
    auto& st = g_bobSwiftInheritTest;

    if (!st.captured ||
        st.pawn != m.bob.pawn) {
        status =
            "Press Capture Swiftness baseline first";
        return false;
    }

    BobTalentLevelRecord r;
    uint64_t addr = 0;
    std::string findStatus;

    if (!BobFindTalentLevelRecordAddress(
            m,
            49,
            addr,
            r,
            findStatus)) {
        status = findStatus;
        return false;
    }

    // We change ONLY FTalentLevel::Inherited.
    if (m.reader.WriteBytes(
            addr + kBobOff_TalentLevel_Inherited,
            &inherited,
            sizeof(inherited)) !=
        sizeof(inherited)) {
        status =
            "Could not write local Swiftness Inherited field";
        return false;
    }

    int32_t verify = 0;
    if (m.reader.ReadBytes(
            addr + kBobOff_TalentLevel_Inherited,
            &verify,
            sizeof(verify)) !=
        sizeof(verify) ||
        verify != inherited) {
        status =
            "Swiftness Inherited write did not verify";
        return false;
    }

    std::string rebuildStatus;
    const bool rebuildOk =
        BobRebuildCurrentTalentMap(
            m,
            g,
            rebuildStatus);

    st.recordAddr = addr;
    st.currentInherited = verify;

    BobRefreshSwiftnessInheritTestReadback(
        m,
        g);

    char b[320];
    std::snprintf(
        b,
        sizeof(b),
        "LOCAL Swiftness test: Points=%d Inherited=%+d | GetTalentMod=%s%.6g | MovementSpeedMod=%s%.6g | rebuild=%s",
        st.currentPoints,
        st.currentInherited,
        st.getModOk ? "" : "? ",
        st.getMod,
        st.movementOk ? "" : "? ",
        st.movementSpeedMod,
        rebuildOk ? "OK" : "FAILED");

    st.status = b;
    status = b;
    return rebuildOk;
}


static bool BobApplyLocalSwiftnessPointsInherited(
    AppModel& m,
    const GameConfig& g,
    int32_t points,
    int32_t inherited,
    std::string& status)
{
    auto& st = g_bobSwiftInheritTest;

    if (!st.captured ||
        st.pawn != m.bob.pawn) {
        status =
            "Press Capture Swiftness baseline first";
        return false;
    }

    BobTalentLevelRecord r;
    uint64_t addr = 0;
    std::string findStatus;

    if (!BobFindTalentLevelRecordAddress(
            m,
            49,
            addr,
            r,
            findStatus)) {
        status = findStatus;
        return false;
    }

    // Controlled LOCAL comparison: change only Points + Inherited.
    // Override and Purchased remain untouched.
    if (m.reader.WriteBytes(
            addr + kBobOff_TalentLevel_Points,
            &points,
            sizeof(points)) !=
        sizeof(points)) {
        status =
            "Could not write local Swiftness Points field";
        return false;
    }

    if (m.reader.WriteBytes(
            addr + kBobOff_TalentLevel_Inherited,
            &inherited,
            sizeof(inherited)) !=
        sizeof(inherited)) {
        // Try to put Points back immediately if the second write failed.
        m.reader.WriteBytes(
            addr + kBobOff_TalentLevel_Points,
            &st.originalPoints,
            sizeof(st.originalPoints));

        status =
            "Could not write local Swiftness Inherited field";
        return false;
    }

    int32_t verifyPoints = 0;
    int32_t verifyInherited = 0;

    const bool pointsOk =
        m.reader.ReadBytes(
            addr + kBobOff_TalentLevel_Points,
            &verifyPoints,
            sizeof(verifyPoints)) ==
            sizeof(verifyPoints) &&
        verifyPoints == points;

    const bool inheritedOk =
        m.reader.ReadBytes(
            addr + kBobOff_TalentLevel_Inherited,
            &verifyInherited,
            sizeof(verifyInherited)) ==
            sizeof(verifyInherited) &&
        verifyInherited == inherited;

    if (!pointsOk || !inheritedOk) {
        status =
            "Swiftness Points/Inherited write did not verify";
        return false;
    }

    std::string rebuildStatus;
    const bool rebuildOk =
        BobRebuildCurrentTalentMap(
            m,
            g,
            rebuildStatus);

    st.recordAddr = addr;
    st.currentPoints = verifyPoints;
    st.currentInherited = verifyInherited;

    BobRefreshSwiftnessInheritTestReadback(
        m,
        g);

    char b[320];
    std::snprintf(
        b,
        sizeof(b),
        "LOCAL Swiftness combo: Points=%d Inherited=%+d | GetTalentMod=%s%.6g | MovementSpeedMod=%s%.6g | rebuild=%s",
        st.currentPoints,
        st.currentInherited,
        st.getModOk ? "" : "? ",
        st.getMod,
        st.movementOk ? "" : "? ",
        st.movementSpeedMod,
        rebuildOk ? "OK" : "FAILED");

    st.status = b;
    status = b;
    return rebuildOk;
}

static bool BobRestoreLocalSwiftnessInherited(
    AppModel& m,
    const GameConfig& g,
    std::string& status)
{
    auto& st = g_bobSwiftInheritTest;

    if (!st.captured ||
        st.pawn != m.bob.pawn) {
        status =
            "No captured Swiftness baseline for this pawn";
        return false;
    }

    return BobApplyLocalSwiftnessPointsInherited(
        m,
        g,
        st.originalPoints,
        st.originalInherited,
        status);
}

static bool BobReadActiveTalentEnums(AppModel& m,
                                     std::unordered_set<uint32_t>& out,
                                     std::string& status)
{
    out.clear();

    std::vector<BobTalentLevelRecord> records;
    if (!BobReadTalentLevelRecords(m, records, status))
        return false;

    for (const BobTalentLevelRecord& r : records) {
        if (r.points != 0 || r.inherited != 0 || r.purchased != 0 ||
            std::fabs(r.overrideValue) > 0.0001f) {
            out.insert(r.talent);
        }
    }

    char b[160];
    std::snprintf(b, sizeof(b),
                  "Found %zu active/current talent records", out.size());
    status = b;
    return true;
}

static bool BobInvokeLocalTalentSetter(AppModel& m, const GameConfig& g,
                                       const char* setterName, float value,
                                       std::string& status)
{
    if (!m.bob.playerController) {
        status = "BoB PlayerController unresolved";
        return false;
    }
    if (!setterName || !*setterName) {
        status = "No local direct setter for this talent";
        return false;
    }

    // All listed APPBasePlayerController SetX talent test functions are
    // Exec, Native, Public and take a single float.  They are NOT SERVER_
    // RPCs.  Parameter struct is exactly 4 bytes.
    std::vector<uint8_t> parms(4, 0);
    std::memcpy(parms.data(), &value, 4);
    std::vector<std::pair<size_t, FStringArg>> noFx;

    return InvokeRpc(m, g, m.bob.playerController,
                     { "PPBasePlayerController" },
                     setterName, parms, noFx, status);
}




static bool BobCaptureAcroTalentBaseline(
    AppModel& m,
    const GameConfig& g,
    std::string& status)
{
    if (g_bobAcroTalent.captured &&
        g_bobAcroTalent.pawn == m.bob.pawn) {
        status = g_bobAcroTalent.status;
        return true;
    }

    BobTalentLevelRecord rec;
    uint64_t addr = 0;
    std::string findStatus;

    if (!BobFindTalentLevelRecordAddress(
            m, 73, addr, rec, findStatus)) {
        status =
            "Intimidating Roar (Acro) needs a real enum 73 "
            "FTalentLevel record: " + findStatus;
        return false;
    }

    BobAcroTalentState st;
    st.pawn = m.bob.pawn;
    st.captured = true;

    if (m.reader.ReadBytes(
            addr,
            st.originalRaw.data(),
            st.originalRaw.size()) !=
        st.originalRaw.size()) {
        status = "Could not capture original enum 73 FTalentLevel";
        return false;
    }

    st.originalPoints = rec.points;
    st.originalInherited = rec.inherited;
    st.originalOverride = rec.overrideValue;
    st.originalPurchased = rec.purchased;

    std::string modStatus;
    st.getModOk =
        BobGetCurrentTalentMod(m, g, 73, st.getMod, modStatus);

    char b[420];
    std::snprintf(
        b,
        sizeof(b),
        "Captured enum 73: Points=%d Inherited=%+d Override=%.6g "
        "Purchased=%d GetTalentMod=%s%.6g",
        st.originalPoints,
        st.originalInherited,
        st.originalOverride,
        st.originalPurchased,
        st.getModOk ? "" : "? ",
        st.getMod);

    st.status = b;
    g_bobAcroTalent = st;
    status = st.status;
    return true;
}

static bool BobApplyAcroTalentModifier(
    AppModel& m,
    const GameConfig& g,
    float requested,
    std::string& status)
{
    BobTalentRowEntry* row = BobFindTalentRow(73);
    if (!row) {
        status = "AcroRoarAbility / enum 73 TalentInfo row is missing";
        return false;
    }

    const float nativeMax = BobAcroTalentNativeMax(*row);
    if (!std::isfinite(nativeMax) || nativeMax <= 1.000001f) {
        status =
            "Enum 73 native Val5 is unavailable/invalid; "
            "capture a clean TalentInfo baseline first";
        return false;
    }

    requested = std::clamp(requested, 1.0f, nativeMax);

    std::string captureStatus;
    if (!BobCaptureAcroTalentBaseline(m, g, captureStatus)) {
        status = captureStatus;
        return false;
    }

    BobTalentLevelRecord currentRec;
    uint64_t addr = 0;
    std::string findStatus;
    if (!BobFindTalentLevelRecordAddress(
            m, 73, addr, currentRec, findStatus)) {
        status = findStatus;
        return false;
    }

    // Start from CURRENT raw bytes so fast-array metadata and current
    // Points/Inherited/Purchased are preserved.
    std::array<uint8_t, kBobSize_FTalentLevel> raw{};
    if (m.reader.ReadBytes(addr, raw.data(), raw.size()) != raw.size()) {
        status = "Could not read current enum 73 FTalentLevel";
        return false;
    }

    std::memcpy(
        raw.data() + kBobOff_TalentLevel_Override,
        &requested,
        sizeof(requested));

    // AH15.12.11.1:
    // DO NOT invoke ABaseCharacter::SetTalentLevel here.
    //
    // Runtime proof from the user's crash:
    //   Assertion failed: GetLocalRole() == ROLE_Authority
    //   BaseCharacter.cpp line 3276
    //
    // SetTalentLevel is an authority-only native path. Calling it directly on
    // the client crashes before any fallback can run. The safe local test is
    // therefore the exact FTalentLevel::Override write we already know how to
    // restore, followed by the local TalentMap rebuild/readback.
    if (m.reader.WriteBytes(
            addr + kBobOff_TalentLevel_Override,
            &requested,
            sizeof(requested)) != sizeof(requested)) {
        status =
            "Enum 73 local Override write failed";
        return false;
    }

    const std::string path =
        "raw local FTalentLevel::Override (authority-safe)";

    // Re-read the fast-array item after the local write.
    BobTalentLevelRecord verifyRec;
    uint64_t verifyAddr = 0;
    std::string verifyFind;
    if (!BobFindTalentLevelRecordAddress(
            m, 73, verifyAddr, verifyRec, verifyFind)) {
        status = "Enum 73 record vanished after apply: " + verifyFind;
        return false;
    }

    const float overrideTol =
        std::max(0.0001f, std::fabs(requested) * 0.0005f);
    if (!std::isfinite(verifyRec.overrideValue) ||
        std::fabs(verifyRec.overrideValue - requested) > overrideTol) {
        char b[320];
        std::snprintf(
            b,
            sizeof(b),
            "Enum 73 Override did not verify: requested %.6g read %.6g",
            requested,
            verifyRec.overrideValue);
        status = b;
        return false;
    }

    std::string rebuildStatus;
    if (!BobRebuildCurrentTalentMap(m, g, rebuildStatus)) {
        status =
            "Enum 73 record changed but TalentMap rebuild failed: " +
            rebuildStatus;
        return false;
    }

    float getMod = 0.0f;
    std::string modStatus;
    if (!BobGetCurrentTalentMod(m, g, 73, getMod, modStatus)) {
        status =
            "Enum 73 Override verified but GetTalentMod(73) failed: " +
            modStatus;
        return false;
    }

    const float modTol =
        std::max(0.001f, std::fabs(requested) * 0.002f);
    if (std::fabs(getMod - requested) > modTol) {
        char b[384];
        std::snprintf(
            b,
            sizeof(b),
            "Enum 73 record updated but GetTalentMod(73)=%.6g "
            "instead of requested %.6g",
            getMod,
            requested);
        status = b;
        return false;
    }

    // Refresh the Acro-specific PC cache only with the verified TalentMap value.
    std::string setterStatus;
    if (!BobInvokeLocalTalentSetter(
            m, g, "SetAcroRoarAbility", getMod, setterStatus)) {
        status =
            "GetTalentMod(73) verified, but SetAcroRoarAbility failed: " +
            setterStatus;
        return false;
    }

    g_bobAcroTalent.applied = true;
    g_bobAcroTalent.requested = requested;
    g_bobAcroTalent.getModOk = true;
    g_bobAcroTalent.getMod = getMod;
    g_bobAcroTalent.lastPath = path;

    char b[700];
    std::snprintf(
        b,
        sizeof(b),
        "Intimidating Roar (Acro) enum 73 LOCAL TEST %.6g "
        "(native V5 %.6g) | Override=%.6g | GetTalentMod(73)=%.6g | "
        "SetAcroRoarAbility OK | gameplay authority NOT changed | path=%s",
        requested,
        nativeMax,
        verifyRec.overrideValue,
        getMod,
        path.c_str());

    g_bobAcroTalent.status = b;
    status = b;
    return true;
}

static bool BobRestoreAcroTalentModifier(
    AppModel& m,
    const GameConfig& g,
    std::string& status)
{
    if (!g_bobAcroTalent.captured) {
        status = "no enum 73 override captured";
        return true;
    }

    if (!m.bob.pawn || g_bobAcroTalent.pawn != m.bob.pawn) {
        status =
            "Acro baseline belongs to a different pawn; stale restore blocked";
        return false;
    }

    BobTalentLevelRecord currentRec;
    uint64_t addr = 0;
    std::string findStatus;
    if (!BobFindTalentLevelRecordAddress(
            m, 73, addr, currentRec, findStatus)) {
        status = findStatus;
        return false;
    }

    std::array<uint8_t, kBobSize_FTalentLevel> restoreRaw{};
    if (m.reader.ReadBytes(
            addr,
            restoreRaw.data(),
            restoreRaw.size()) != restoreRaw.size()) {
        status = "Could not read current enum 73 record for restore";
        return false;
    }

    // Preserve current FFastArraySerializerItem metadata [0x00..0x0B].
    // Restore the FTalentLevel payload [Talent..PurchasedInherits].
    std::memcpy(
        restoreRaw.data() + kBobOff_TalentLevel_Talent,
        g_bobAcroTalent.originalRaw.data() + kBobOff_TalentLevel_Talent,
        kBobSize_FTalentLevel - kBobOff_TalentLevel_Talent);

    // Authority-safe restore: never call ABaseCharacter::SetTalentLevel from
    // the client. Restore only the captured FTalentLevel payload while keeping
    // current FFastArraySerializerItem metadata intact.
    const size_t payloadBytes =
        kBobSize_FTalentLevel - kBobOff_TalentLevel_Talent;

    if (m.reader.WriteBytes(
            addr + kBobOff_TalentLevel_Talent,
            restoreRaw.data() + kBobOff_TalentLevel_Talent,
            payloadBytes) != payloadBytes) {
        status =
            "Raw enum 73 FTalentLevel payload restore failed";
        return false;
    }

    std::string rebuildStatus;
    if (!BobRebuildCurrentTalentMap(m, g, rebuildStatus)) {
        status =
            "Enum 73 restored but TalentMap rebuild failed: " +
            rebuildStatus;
        return false;
    }

    float normalMod = 0.0f;
    std::string modStatus;
    if (!BobGetCurrentTalentMod(m, g, 73, normalMod, modStatus)) {
        status =
            "Enum 73 payload restored but GetTalentMod(73) failed: " +
            modStatus;
        return false;
    }

    std::string setterStatus;
    if (!BobInvokeLocalTalentSetter(
            m, g, "SetAcroRoarAbility", normalMod, setterStatus)) {
        status =
            "Enum 73 restored but SetAcroRoarAbility failed: " +
            setterStatus;
        return false;
    }

    char b[560];
    std::snprintf(
        b,
        sizeof(b),
        "Restored Intimidating Roar (Acro) enum 73: "
        "Points=%d Inherited=%+d Override=%.6g Purchased=%d | "
        "GetTalentMod(73)=%.6g | SetAcroRoarAbility OK",
        g_bobAcroTalent.originalPoints,
        g_bobAcroTalent.originalInherited,
        g_bobAcroTalent.originalOverride,
        g_bobAcroTalent.originalPurchased,
        normalMod);

    status = b;
    g_bobAcroTalent = BobAcroTalentState{};
    return true;
}


// ============================================================================
// AH15.12.12 — enum73 server-authority probe
//
// This does NOT call the authority-only native SetTalentLevel() locally.
// Instead it invokes the replicated SERVER_SetTalentLevel UFunction on the
// locally-owned ABaseCharacter. UE routes the request to the server.
//
// BoB_RPCs.md classifies SERVER_SetTalentLevel as permission-gated/protected.
// Xen does not bypass that gate. The server can accept or reject the request.
// ============================================================================

static bool BobRefreshAcroServerProbeReadback(
    AppModel& m,
    const GameConfig& g,
    std::string& status)
{
    BobTalentLevelRecord r;
    uint64_t addr = 0;
    std::string findStatus;

    if (!BobFindTalentLevelRecordAddress(
            m, 73, addr, r, findStatus)) {

        g_bobAcroServerProbe.readbackFound = false;
        g_bobAcroServerProbe.getModOk = false;
        status =
            "Enum73 replicated readback unavailable: " +
            findStatus;
        g_bobAcroServerProbe.status = status;
        return false;
    }

    auto& st = g_bobAcroServerProbe;

    st.readbackFound = true;
    st.readbackPoints = r.points;
    st.readbackInherited = r.inherited;
    st.readbackOverride = r.overrideValue;
    st.readbackPurchased = r.purchased;

    std::string modStatus;

    st.getModOk =
        BobGetCurrentTalentMod(
            m, g, 73, st.getMod, modStatus);

    if (st.getModOk) {
        std::string setterStatus;
        BobInvokeLocalTalentSetter(
            m, g, "SetAcroRoarAbility",
            st.getMod, setterStatus);
    }

    std::ostringstream oss;
    oss
        << "Enum73 readback: Points=" << st.readbackPoints
        << " Inherited="
        << (st.readbackInherited >= 0 ? "+" : "")
        << st.readbackInherited
        << " Override=" << st.readbackOverride
        << " Purchased=" << st.readbackPurchased;

    if (st.getModOk)
        oss << " GetTalentMod(73)=" << st.getMod;
    else
        oss << " GetTalentMod(73)=unavailable";

    if (st.dispatched) {
        if (st.readbackPoints == st.requestedPoints)
            oss << " | requested Points ACCEPTED/REPLICATED";
        else
            oss << " | requested Points NOT observed";
    }

    status = oss.str();
    st.status = status;
    return true;
}

static bool BobDispatchAcroServerTalentPoints(
    AppModel& m,
    const GameConfig& g,
    int requestedPoints,
    std::string& status)
{
    if (!m.bob.pawn) {
        status = "BoB pawn unresolved";
        return false;
    }

    BobTalentRowEntry* row =
        BobFindTalentRow(73);

    if (!row) {
        status =
            "AcroRoarAbility / enum73 TalentInfo row missing";
        return false;
    }

    requestedPoints =
        std::clamp(requestedPoints, 1, 5);

    if (!g_bobAcroTalent.captured) {
        std::string captureStatus;
        if (!BobCaptureAcroTalentBaseline(
                m, g, captureStatus)) {
            status = captureStatus;
            return false;
        }
    }

    BobTalentLevelRecord current;
    uint64_t currentAddr = 0;
    std::string findStatus;

    if (!BobFindTalentLevelRecordAddress(
            m, 73, currentAddr, current, findStatus)) {
        status = findStatus;
        return false;
    }

    std::array<uint8_t, kBobSize_FTalentLevel> raw{};

    if (m.reader.ReadBytes(
            currentAddr,
            raw.data(),
            raw.size()) != raw.size()) {
        status =
            "Could not read current enum73 FTalentLevel bytes";
        return false;
    }

    const uint8_t talent = 73;
    const int32_t points = requestedPoints;
    const int32_t inherited = current.inherited;
    const float overrideValue = 0.0f;
    const int32_t purchased = current.purchased;

    std::memcpy(
        raw.data() + kBobOff_TalentLevel_Talent,
        &talent, 1);

    std::memcpy(
        raw.data() + kBobOff_TalentLevel_Points,
        &points, 4);

    std::memcpy(
        raw.data() + kBobOff_TalentLevel_Inherited,
        &inherited, 4);

    std::memcpy(
        raw.data() + kBobOff_TalentLevel_Override,
        &overrideValue, 4);

    std::memcpy(
        raw.data() + kBobOff_TalentLevel_Purchased,
        &purchased, 4);

    // SERVER_SetTalentLevel params:
    // +0x00 FTalentLevel(0x20), +0x20 bForce, +0x21 bBypassInheritCheck.
    std::vector<uint8_t> parms(0x28, 0);
    std::memcpy(parms.data(), raw.data(), raw.size());
    parms[0x20] = 1;
    parms[0x21] = 0;

    std::vector<std::pair<size_t, FStringArg>> noFx;
    std::string rpcStatus;

    const bool dispatched =
        InvokeRpc(
            m,
            g,
            m.bob.pawn,
            { "BaseCharacter" },
            "SERVER_SetTalentLevel",
            parms,
            noFx,
            rpcStatus);

    auto& st = g_bobAcroServerProbe;
    st.dispatched = dispatched;
    st.requestedPoints = requestedPoints;
    st.expectedModifier =
        BobAcroTalentNativeValueForPoints(
            *row, requestedPoints);

    if (!dispatched) {
        status =
            "SERVER_SetTalentLevel dispatch failed: " +
            rpcStatus;
        st.status = status;
        return false;
    }

    std::ostringstream oss;
    oss
        << "SERVER_SetTalentLevel dispatched for enum73 Points="
        << requestedPoints
        << " expected native modifier="
        << st.expectedModifier
        << ". Server acceptance is permission-gated. "
           "Wait about 1 second, then refresh authoritative readback.";

    status = oss.str();
    st.status = status;
    return true;
}

static bool BobDispatchAcroServerRestore(
    AppModel& m,
    const GameConfig& g,
    std::string& status)
{
    if (!g_bobAcroTalent.captured) {
        status =
            "No original enum73 baseline captured for server restore";
        return false;
    }

    if (!m.bob.pawn ||
        g_bobAcroTalent.pawn != m.bob.pawn) {
        status =
            "Captured enum73 baseline belongs to a different pawn";
        return false;
    }

    BobTalentLevelRecord current;
    uint64_t currentAddr = 0;
    std::string findStatus;

    if (!BobFindTalentLevelRecordAddress(
            m, 73, currentAddr, current, findStatus)) {
        status = findStatus;
        return false;
    }

    std::array<uint8_t, kBobSize_FTalentLevel> raw{};

    if (m.reader.ReadBytes(
            currentAddr,
            raw.data(),
            raw.size()) != raw.size()) {
        status =
            "Could not read current enum73 bytes for server restore";
        return false;
    }

    std::memcpy(
        raw.data() + kBobOff_TalentLevel_Talent,
        g_bobAcroTalent.originalRaw.data() +
            kBobOff_TalentLevel_Talent,
        kBobSize_FTalentLevel -
            kBobOff_TalentLevel_Talent);

    std::vector<uint8_t> parms(0x28, 0);
    std::memcpy(parms.data(), raw.data(), raw.size());
    parms[0x20] = 1;
    parms[0x21] = 0;

    std::vector<std::pair<size_t, FStringArg>> noFx;
    std::string rpcStatus;

    const bool dispatched =
        InvokeRpc(
            m,
            g,
            m.bob.pawn,
            { "BaseCharacter" },
            "SERVER_SetTalentLevel",
            parms,
            noFx,
            rpcStatus);

    if (!dispatched) {
        status =
            "SERVER enum73 restore dispatch failed: " +
            rpcStatus;
        g_bobAcroServerProbe.status = status;
        return false;
    }

    std::ostringstream oss;
    oss
        << "SERVER enum73 restore dispatched: original Points="
        << g_bobAcroTalent.originalPoints
        << " Inherited="
        << (g_bobAcroTalent.originalInherited >= 0 ? "+" : "")
        << g_bobAcroTalent.originalInherited
        << " Override="
        << g_bobAcroTalent.originalOverride
        << ". Wait about 1 second and refresh authoritative readback.";

    status = oss.str();
    g_bobAcroServerProbe.status = status;
    return true;
}

static bool BobForceDirectTalentRefresh(AppModel& m, const GameConfig& g,
                                        std::string& status)
{
    std::unordered_set<uint32_t> active;
    std::string activeStatus;
    if (!BobReadActiveTalentEnums(m, active, activeStatus)) {
        status = activeStatus;
        return false;
    }

    int queried = 0;
    int settersOk = 0;
    int settersFail = 0;
    std::string lastFailure;

    // Refresh diagnostics for all mapped priority rows while we are already
    // walking the active FTalentLevel set.
    for (const auto& spec : kBobPriorityTalents) {
        if (spec.talent >= g_bobTalentPipelineDiag.size()) continue;
        BobTalentPipelineDiag& d =
            g_bobTalentPipelineDiag[(size_t)spec.talent];
        d = BobTalentPipelineDiag{};
        d.valid = true;
        d.setterMapped = spec.localSetter && *spec.localSetter;
        d.activeRecord = active.find(spec.talent) != active.end();

        const BobTalentRowEntry* row = BobFindTalentRow(spec.talent);
        d.rowFound = row != nullptr;
        if (row) {
            std::string baselineWhy;
            BobGetTalentBaselineHealth(*row, &baselineWhy);
            d.baseline = baselineWhy;
        }
    }

    for (const auto& spec : kBobPriorityTalents) {
        const BobTalentRowEntry* row = BobFindTalentRow(spec.talent);
        if (!row) continue;

        const uint8_t leader =
            BobTalentControlLeader(spec.talent);

        // Swiftness is driven by the real FTalentLevel Points/Inherited state.
        // Do not locally push SetSpeedIncrease or any coupled ground row.
        if (BobTalentControlIsDisplayOnly(leader))
            continue;

        // Direct cache refresh must not inherit the table-write protection
        // switches. A protected row is already vanilla in TalentInfo, and its
        // local SetX cache still needs that vanilla value pushed during Reset.
        // The same rule fixes stale cached values left by an earlier build.
        if (!spec.localSetter) continue;

        // Normally a local SetX refresh is relevant only to a talent that has a
        // live FTalentLevel record. In zero-point 5/3 preview mode Val0 is
        // deliberately patched, so supported SetX wrappers are also allowed to
        // consume GetTalentMod() with no positive point invested.
        const bool hasLiveTalentRecord =
            active.find(spec.talent) != active.end();
        if (!hasLiveTalentRecord && !g_bobTalentZeroPointFiveOfThree)
            continue;

        float mod = 0.0f;
        std::string s;
        BobTalentPipelineDiag* diag =
            spec.talent < g_bobTalentPipelineDiag.size()
                ? &g_bobTalentPipelineDiag[(size_t)spec.talent]
                : nullptr;

        if (!BobGetCurrentTalentMod(m, g, spec.talent, mod, s)) {
            if (diag) {
                diag->getModOk = false;
                diag->note = "GetTalentMod failed: " + s;
            }
            ++settersFail;
            lastFailure = std::string(spec.label) + " GetTalentMod: " + s;
            continue;
        }
        ++queried;
        if (diag) {
            diag->getModOk = true;
            diag->getMod = mod;
            diag->setterAttempted = true;
        }

        if (BobInvokeLocalTalentSetter(m, g, spec.localSetter, mod, s)) {
            if (diag) {
                diag->setterOk = true;
                diag->note = std::string(spec.localSetter) + " fired";
            }
            ++settersOk;
        } else {
            if (diag) {
                diag->setterOk = false;
                diag->note = std::string(spec.localSetter) + " failed: " + s;
            }
            ++settersFail;
            lastFailure = std::string(spec.label) + " " + spec.localSetter + ": " + s;
        }
    }

    char b[640];
    if (settersFail == 0) {
        std::snprintf(
            b, sizeof(b),
            "Direct/cached refresh: %d mapped talent modifiers queried, "
            "%d local SetX wrappers fired",
            queried, settersOk);
        status = b;
        return true;
    }

    std::snprintf(
        b, sizeof(b),
        "Direct/cached refresh: %d setters OK, %d failed. Last: %s",
        settersOk, settersFail, lastFailure.c_str());
    status = b;
    return false;
}





static bool BobForceDirtyExactTalentTargets(AppModel& m, const GameConfig& g,
                                             std::string& status)
{
    std::unordered_set<uint32_t> active;
    std::string activeStatus;
    if (!BobReadActiveTalentEnums(m, active, activeStatus)) {
        status = activeStatus;
        return false;
    }

    int attempted = 0;
    int ok = 0;
    int failed = 0;
    std::string lastFailure;

    for (const auto& spec : kBobPriorityTalents) {
        if (!spec.localSetter || !*spec.localSetter)
            continue;

        if (spec.talent == 73)
            continue;

        const uint8_t leader = BobTalentControlLeader(spec.talent);

        if (BobTalentControlIsDisplayOnly(leader))
            continue;

        // Hybrid AF: problem/risk rows remain editable, but their SetX refresh
        // only fires when the user explicitly enables manual-risk application.
        if (BobTalentControlIsRuntimeUnsafe(leader) &&
            !g_bobTalentApplyManualRiskRows)
            continue;
        if (!g_bobTalentCustomDirty[(size_t)leader])
            continue;

        // Keep the same ownership rule as the existing direct-refresh path.
        // A SetX modifier is meaningful for an owned/current talent record;
        // zero-point preview deliberately allows the Val0 path as well.
        const bool hasLiveTalentRecord =
            active.find(spec.talent) != active.end();
        if (!hasLiveTalentRecord && !g_bobTalentZeroPointFiveOfThree)
            continue;

        float target = g_bobTalentCustomModifier[(size_t)leader];
        const float maxTarget = kBobTalentTypedMax;
        target = std::clamp(target, kBobTalentTypedMin, maxTarget);

        ++attempted;
        std::string one;
        if (BobInvokeLocalTalentSetter(m, g, spec.localSetter, target, one)) {
            ++ok;

            if (spec.talent < g_bobTalentPipelineDiag.size()) {
                BobTalentPipelineDiag& d =
                    g_bobTalentPipelineDiag[(size_t)spec.talent];
                d.valid = true;
                d.setterMapped = true;
                d.activeRecord = hasLiveTalentRecord;
                d.setterAttempted = true;
                d.setterOk = true;
                d.getMod = target;
                d.note = std::string(spec.localSetter) +
                         " exact slider target fired";
            }
        } else {
            ++failed;
            lastFailure = std::string(spec.label) + " " +
                          spec.localSetter + ": " + one;
        }
    }

    char b[640];
    if (failed == 0) {
        std::snprintf(
            b, sizeof(b),
            "Exact direct refresh: %d requested SetX targets fired (%d OK)",
            attempted, ok);
        status = b;
        return true;
    }

    std::snprintf(
        b, sizeof(b),
        "Exact direct refresh: %d OK, %d failed. Last: %s",
        ok, failed, lastFailure.c_str());
    status = b;
    return false;
}

static void BobRefreshMapOnlyTalentDiagnostics(
    AppModel& m, const GameConfig& g)
{
    std::unordered_set<uint32_t> active;
    std::string activeStatus;
    const bool activeOk =
        BobReadActiveTalentEnums(m, active, activeStatus);

    for (const auto& spec : kBobPriorityTalents) {
        if (spec.talent >= g_bobTalentPipelineDiag.size())
            continue;

        // Mapped SetX rows are filled by BobForceDirectTalentRefresh when that
        // path is enabled. This function mainly makes map-only talents such as
        // Forager visible even though they have no SetForager developer setter.
        BobTalentPipelineDiag& d =
            g_bobTalentPipelineDiag[(size_t)spec.talent];

        if (!d.valid) {
            d.valid = true;
            d.setterMapped = spec.localSetter && *spec.localSetter;
        }

        const BobTalentRowEntry* row =
            BobFindTalentRow(spec.talent);
        d.rowFound = row != nullptr;
        if (row) {
            std::string baselineWhy;
            BobGetTalentBaselineHealth(*row, &baselineWhy);
            d.baseline = baselineWhy;
        }

        if (activeOk)
            d.activeRecord =
                active.find(spec.talent) != active.end();

        // Always query the two talents currently under investigation; for
        // other map-only priority rows query only when they are active or when
        // zero-point preview is enabled.
        const bool mustQuery =
            spec.talent == 6 ||
            spec.talent == 73 ||
            spec.talent == 102 ||
            d.activeRecord ||
            g_bobTalentZeroPointFiveOfThree;

        if (!mustQuery || !row) continue;

        float mod = 0.0f;
        std::string s;
        if (BobGetCurrentTalentMod(m, g, spec.talent, mod, s)) {
            d.getModOk = true;
            d.getMod = mod;

            if (!d.setterMapped) {
                d.note =
                    "TalentMap/GetTalentMod only (no proven local SetX wrapper)";
            } else if (!d.setterAttempted) {
                d.note =
                    "SetX exists but direct refresh was not run";
            }
        } else {
            d.getModOk = false;
            if (d.note.empty())
                d.note = "GetTalentMod failed: " + s;
        }
    }
}


static bool BobApplyCustomTalentSliders(AppModel& m, const GameConfig& g,
                                        bool forceDirectRefresh,
                                        std::string& status)
{
    std::string captureStatus;
    if (!BobCaptureTalentRows(m, captureStatus)) {
        status = captureStatus;
        return false;
    }
    BobEnsureTalentCustomSliders();

    int controlsDirty = 0;
    int rowsAttempted = 0;
    int rowsVerified = 0;
    int rowsFailed = 0;
    int movementProtected = 0;
    int legacyProtected = 0;
    int manualRiskSkipped = 0;
    int displayOnlySkipped = 0;
    int zeroPointBoosted = 0;

    bool acroDirty = false;
    bool acroOk = true;
    float acroTarget = 1.0f;
    std::string acroStatus = "enum 73 unchanged";

    for (auto& e : g_bobTalentRows) {
        const uint8_t leader = BobTalentControlLeader(e.talent);

        const bool isAsphy = BobTalentControlHasAsphyxiation(leader);

        // Never flatten/patch display-only controls locally.
        // Swiftness remains REAL-INHERIT diagnostic-only; Back Up is disabled
        // entirely from the modifier pipeline after prior instability.
        if (BobTalentControlIsDisplayOnly(leader)) {
            if (g_bobTalentCustomDirty[(size_t)leader] &&
                e.talent == leader) {
                ++displayOnlySkipped;
            }
            continue;
        }

        // Intimidating Roar (Acro) / enum 73 keeps its native TalentInfoData
        // curve. A dirty target is applied later through its real FTalentLevel.
        if (leader == 73) {
            if (e.talent == leader &&
                g_bobTalentCustomDirty[(size_t)leader]) {
                const float nativeMax = BobAcroTalentNativeMax(e);
                acroTarget = std::clamp(
                    g_bobTalentCustomModifier[(size_t)leader],
                    1.0f,
                    nativeMax);
                g_bobTalentCustomModifier[(size_t)leader] = acroTarget;
                acroDirty = true;
                ++controlsDirty;
            }
            continue;
        }

        // Hybrid AF: known problem/risk rows are MANUAL-RISK. Their controls
        // always stay editable, but Apply skips them unless the explicit UI
        // checkbox is enabled. Skipped dirty controls stay dirty/pending.
        if (BobTalentIsMovementSensitive(e)) ++movementProtected;
        if (BobTalentIsDisabled(e.talent)) ++legacyProtected;
        if (!isAsphy && BobTalentControlIsRuntimeUnsafe(leader) &&
            !g_bobTalentApplyManualRiskRows) {
            if (g_bobTalentCustomDirty[(size_t)leader] && e.talent == leader)
                ++manualRiskSkipped;
            continue;
        }

        // Only changed controls are written, EXCEPT Asphyxiation. Drown-damage
        // modifier is fixed at 5.0 in this branch whenever talent changes apply.
        if (!g_bobTalentCustomDirty[(size_t)leader] && !isAsphy)
            continue;

        if (e.talent == leader)
            ++controlsDirty;

        float target = isAsphy ? 5.0f
                               : g_bobTalentCustomModifier[(size_t)leader];
        const float maxTarget = kBobTalentTypedMax;
        target = std::clamp(target, kBobTalentTypedMin, maxTarget);
        g_bobTalentCustomModifier[(size_t)leader] = target;
        if (isAsphy)
            g_bobTalentCustomDirty[(size_t)leader] = true;

        // Exact-modifier semantics: every positive talent tier receives the
        // requested target. Therefore an active 1/3, 3/3, inherited, etc. row
        // resolves to the same requested local modifier.
        float values[6] = {
            g_bobTalentZeroPointFiveOfThree ? target : e.original[1],
            target, target, target, target, target
        };

        const size_t bytes = sizeof(values);
        ++rowsAttempted;
        if (m.reader.WriteBytes(e.row + kBobOff_TalentRow_Val0,
                                values, bytes) != bytes) {
            ++rowsFailed;
            continue;
        }

        float verify[6] = {};
        if (m.reader.ReadBytes(e.row + kBobOff_TalentRow_Val0,
                               verify, bytes) != bytes) {
            ++rowsFailed;
            continue;
        }

        bool same = true;
        for (int i = 0; i < 6; ++i) {
            const float tol = std::max(0.0001f, std::fabs(values[i]) * 0.0005f);
            if (!std::isfinite(verify[i]) ||
                std::fabs(verify[i] - values[i]) > tol) {
                same = false;
                break;
            }
        }
        if (!same) {
            ++rowsFailed;
            continue;
        }

        for (int i = 0; i < 6; ++i)
            e.live[(size_t)i + 1] = verify[i];

        if (g_bobTalentZeroPointFiveOfThree)
            ++zeroPointBoosted;
        ++rowsVerified;
    }

    if (controlsDirty == 0) {
        if (manualRiskSkipped > 0) {
            status = "Manual-risk talent changes are pending; enable 'Apply manual-risk talents when pressing Apply' to write them";
        } else {
            status = "No talent modifier sliders changed";
        }
        return false;
    }

    g_bobTalentModified =
        rowsVerified > 0 ||
        acroDirty;

    std::string rebuildStatus;
    const bool rebuildOk = BobRebuildCurrentTalentMap(m, g, rebuildStatus);

    if (acroDirty) {
        if (rebuildOk) {
            acroOk =
                BobApplyAcroTalentModifier(
                    m, g, acroTarget, acroStatus);
        } else {
            acroOk = false;
            acroStatus =
                "Skipped enum 73 real-record apply because the initial "
                "TalentMap rebuild failed";
        }
    }

    bool directOk = true;
    std::string directStatus = "direct refresh disabled";
    if (forceDirectRefresh && rebuildOk) {
        // IMPORTANT: on APPLY, do not round-trip the requested value through
        // GetTalentMod(). That map value can remain cached after an earlier
        // apply/restore cycle and would overwrite a newly selected target.
        // Dirty mapped talents therefore receive the slider's exact requested
        // value directly through their confirmed local SetX wrapper.
        // Restore still uses BobForceDirectTalentRefresh() after putting the
        // captured vanilla table back, because there we WANT the game's normal
        // rebuilt GetTalentMod value.
        directOk = BobForceDirtyExactTalentTargets(m, g, directStatus);
    }

    if (rebuildOk)
        BobRefreshMapOnlyTalentDiagnostics(m, g);

    // Clear dirty after an apply. Manual-only risk controls are allowed to write
    // when deliberately changed, so they clear exactly like normal controls.
    for (const auto& row : g_bobTalentRows) {
        const uint8_t leader = BobTalentControlLeader(row.talent);
        if (leader != row.talent) continue;
        if (!g_bobTalentCustomDirty[(size_t)leader]) continue;

        if (BobTalentControlIsDisplayOnly(leader)) {
            g_bobTalentCustomDirty[(size_t)leader] = false;
            continue;
        }

        if (leader == 73 && acroDirty && !acroOk) {
            continue;
        }

        // If a manual-risk control was skipped, leave it dirty so enabling the
        // checkbox later applies the already-prepared target.
        if (BobTalentControlIsRuntimeUnsafe(leader) &&
            !g_bobTalentApplyManualRiskRows)
            continue;
        // Asphyxiation is intentionally re-armed at fixed target 5.0.
        if (BobTalentControlHasAsphyxiation(leader)) {
            g_bobTalentCustomModifier[(size_t)leader] = 5.0f;
            g_bobTalentCustomDirty[(size_t)leader] = true;
            continue;
        }
        g_bobTalentCustomDirty[(size_t)leader] = false;
    }

    char b[1300];
    std::snprintf(
        b, sizeof(b),
        "Exact talent modifiers: changed-controls=%d rows=%d verified=%d "
        "failures=%d movement-risk=%d legacy-risk=%d manual-risk-skipped=%d "
        "display-only-skipped=%d Val0-target=%d; map=%s; acro73=%s; %s",
        controlsDirty, rowsAttempted, rowsVerified, rowsFailed,
        movementProtected, legacyProtected, manualRiskSkipped,
        displayOnlySkipped, zeroPointBoosted,
        rebuildOk ? "OK" : rebuildStatus.c_str(),
        acroDirty ? acroStatus.c_str() : "unchanged",
        forceDirectRefresh ? directStatus.c_str()
                           : "direct refresh disabled");
    status = b;

    return (rowsAttempted > 0 || acroDirty) &&
           rowsVerified == rowsAttempted &&
           rowsFailed == 0 &&
           rebuildOk &&
           (!acroDirty || acroOk) &&
           (!forceDirectRefresh || directOk);
}


// Restore the pawn's LOCAL movement cache to whatever the game's current
// normal talent state computes after TalentInfo has been restored.  This is
// used by the F7 safety hotkey so an earlier raw Swiftness preview cannot leave
// MovementSpeedMod stuck at the preview value.

static bool BobRestoreTalentRows(AppModel& m, const GameConfig& g,
                                 bool forceDirectRefresh,
                                 std::string& status)
{
    if (g_bobTalentRows.empty() || !g_bobTalentTable) {
        status = "No captured TalentInfo originals to restore";
        return false;
    }
    if (!g_bobTalentNativeReferenceTrusted) {
        status = "Restore normal blocked: captured baseline is untrusted. " +
                 g_bobTalentNativeReferenceWhy;
        return false;
    }

    // Refuse to write stale row pointers from a prior table/session.
    uint64_t tableNow = 0;
    if (m.bob.gameInstance) {
        tableNow = BobTalentReadPtr(
            m, m.bob.gameInstance + kBobOff_GI_TalentInfoTable);
    }
    if (!tableNow || tableNow != g_bobTalentTable) {
        status = "TalentInfo table changed; cached row pointers are stale";
        BobClearTalentCache();
        return false;
    }

    int restored = 0;
    int failed = 0;
    for (auto& e : g_bobTalentRows) {
        const size_t bytes = e.original.size() * sizeof(float);
        if (m.reader.WriteBytes(e.row + kBobOff_TalentRow_Neg1,
                                e.original.data(), bytes) != bytes) {
            ++failed;
            continue;
        }

        std::array<float, 7> verify{};
        if (m.reader.ReadBytes(e.row + kBobOff_TalentRow_Neg1,
                               verify.data(), bytes) != bytes) {
            ++failed;
            continue;
        }

        bool same = true;
        for (size_t j = 0; j < verify.size(); ++j) {
            if (!std::isfinite(verify[j]) ||
                std::fabs(verify[j] - e.original[j]) >
                    std::max(0.0001f, std::fabs(e.original[j]) * 0.0005f)) {
                same = false;
                break;
            }
        }
        if (!same) {
            ++failed;
            continue;
        }

        e.live = verify;
        ++restored;
    }

    // Hybrid AD policy: Restore returns every normal row to its captured
    // baseline, but Asphyxiation is intentionally kept fixed at 5.0. Apply the
    // fixed positive-tier value before the one TalentMap rebuild below.
    int asphyFixedRows = 0;
    for (auto& e : g_bobTalentRows) {
        if (!BobTalentIsAsphyxiation(e)) continue;
        float fixedPositive[5] = { 5.0f, 5.0f, 5.0f, 5.0f, 5.0f };
        const size_t fixedBytes = sizeof(fixedPositive);
        if (m.reader.WriteBytes(e.row + kBobOff_TalentRow_Val1,
                                fixedPositive, fixedBytes) == fixedBytes) {
            float verifyFixed[5] = {};
            if (m.reader.ReadBytes(e.row + kBobOff_TalentRow_Val1,
                                   verifyFixed, fixedBytes) == fixedBytes) {
                bool ok = true;
                for (float v : verifyFixed)
                    if (!std::isfinite(v) || std::fabs(v - 5.0f) > 0.0005f)
                        ok = false;
                if (ok) {
                    for (int j = 0; j < 5; ++j)
                        e.live[(size_t)j + 2] = 5.0f;
                    ++asphyFixedRows;
                } else {
                    ++failed;
                }
            } else {
                ++failed;
            }
        } else {
            ++failed;
        }
    }

    g_bobTalentLastEquivalent = 1.0f;
    g_bobTalentModified = failed != 0;

    // Reset the visible exact-modifier controls and clear every dirty flag.
    // Seed each control from its captured Val1 for display only; nothing is
    // re-applied until the user moves a slider again.
    if (failed == 0) {
        g_bobTalentCustomInitialized = false;
        BobEnsureTalentCustomSliders();
        g_bobTalentCustomDirty.fill(false);
        for (const auto& row : g_bobTalentRows) {
            const uint8_t leader = BobTalentControlLeader(row.talent);
            if (leader != row.talent) continue;
            if (BobTalentControlHasAsphyxiation(leader)) {
                g_bobTalentCustomModifier[(size_t)leader] = 5.0f;
                g_bobTalentCustomDirty[(size_t)leader] = true;
            }
        }
        g_bobTalentZeroPointFiveOfThree = false;
    }

    bool acroRestoreOk = true;
    std::string acroRestoreStatus = "no enum 73 override captured";
    if (g_bobAcroTalent.captured) {
        acroRestoreOk =
            BobRestoreAcroTalentModifier(
                m, g, acroRestoreStatus);
    }

    std::string rebuildStatus;
    const bool rebuildOk = BobRebuildCurrentTalentMap(m, g, rebuildStatus);

    bool directOk = true;
    std::string directStatus = "direct refresh skipped";
    if (forceDirectRefresh && rebuildOk) {
        directOk = BobForceDirectTalentRefresh(m, g, directStatus);
    }

    char b[1100];
    std::snprintf(
        b, sizeof(b),
        "Restored TalentInfo rows=%d failures=%d; Asphyxiation fixed-5 rows=%d; "
        "acro73=%s; map rebuild=%s; %s",
        restored, failed, asphyFixedRows,
        acroRestoreStatus.c_str(),
        rebuildOk ? "OK" : rebuildStatus.c_str(),
        forceDirectRefresh ? directStatus.c_str() : "direct refresh disabled");
    status = b;

    return failed == 0 && restored > 0 &&
           acroRestoreOk &&
           rebuildOk && (!forceDirectRefresh || directOk);
}


// ============================================================================
// BoB Tick Lab — SDK-backed, no SERVER_ calls.
// The current SDK exposes ABaseCharacter::DryTickSpeed plus independent
// ResourcesTickTH / ClientStatTickTimerHandle handles and ProcessFoodTick /
// ProcessWaterTick / ProcessGrowthTick / ProcessHealthTick / ResourceTick
// functions.  Dumper-7 does not include the native timer setup bodies, so this
// lab intentionally OBSERVES client-visible stat changes and offers one
// reversible DryTickSpeed field experiment rather than editing FTimerHandle
// internals or repeatedly firing tick functions.
// ============================================================================
struct BobTickMetric {
    bool initialized = false;
    float value = 0.0f;
    double lastChangeS = 0.0;
    double lastIntervalMs = 0.0;
    double intervalSumMs = 0.0;
    uint64_t intervalSamples = 0;
    uint64_t changes = 0;
};

struct BobTickLabState {
    bool observing = false;
    uint64_t pawn = 0;
    uint64_t compStats = 0;
    double lastPollS = 0.0;

    float dryTickLive = 0.0f;

    float foodDecayRate = 0.0f;
    float waterDecayRate = 0.0f;
    float healRate = 0.0f;
    uint64_t resourcesTimerHandle = 0;
    uint64_t clientStatTimerHandle = 0;

    BobTickMetric food;
    BobTickMetric water;
    BobTickMetric growth;
    BobTickMetric injury;
    BobTickMetric health;

    std::string status = "Not sampled yet";
};

static BobTickLabState g_bobTickLab;

static void BobTickMetricReset(BobTickMetric& m)
{
    m = BobTickMetric{};
}

static void BobTickLabResetMetrics()
{
    BobTickMetricReset(g_bobTickLab.food);
    BobTickMetricReset(g_bobTickLab.water);
    BobTickMetricReset(g_bobTickLab.growth);
    BobTickMetricReset(g_bobTickLab.injury);
    BobTickMetricReset(g_bobTickLab.health);
}

static void BobTickMetricObserve(BobTickMetric& m, float value, double nowS)
{
    if (!std::isfinite(value)) return;

    if (!m.initialized) {
        m.initialized = true;
        m.value = value;
        return;
    }

    const float tol = std::max(0.000001f, std::fabs(m.value) * 0.000001f);
    if (std::fabs(value - m.value) <= tol) return;

    if (m.lastChangeS > 0.0) {
        m.lastIntervalMs = (nowS - m.lastChangeS) * 1000.0;
        m.intervalSumMs += m.lastIntervalMs;
        ++m.intervalSamples;
    }

    m.lastChangeS = nowS;
    m.value = value;
    ++m.changes;
}

static void BobTickLabCapturePawnFields(AppModel& m)
{
    if (!m.bob.pawn) return;

    float dry = 0.0f;
    if (m.reader.ReadBytes(m.bob.pawn + bob::kOff_BC_DryTickSpeed,
                           &dry, sizeof(dry)) == sizeof(dry) &&
        std::isfinite(dry) && std::fabs(dry) < 100000.0f) {
        g_bobTickLab.dryTickLive = dry;
    }

    m.reader.ReadBytes(m.bob.pawn + bob::kOff_BC_FoodDecayRate,
                       &g_bobTickLab.foodDecayRate, sizeof(float));
    m.reader.ReadBytes(m.bob.pawn + bob::kOff_BC_WaterDecayRate,
                       &g_bobTickLab.waterDecayRate, sizeof(float));
    m.reader.ReadBytes(m.bob.pawn + bob::kOff_BC_HealRate,
                       &g_bobTickLab.healRate, sizeof(float));

    m.reader.ReadBytes(m.bob.pawn + bob::kOff_BC_ResourcesTickTH,
                       &g_bobTickLab.resourcesTimerHandle, sizeof(uint64_t));
    m.reader.ReadBytes(m.bob.pawn + bob::kOff_BC_ClientStatTickTimerHandle,
                       &g_bobTickLab.clientStatTimerHandle, sizeof(uint64_t));
}

static void BobTickLabPoll(AppModel& m)
{
    if (!g_bobTickLab.observing) return;
    if (m.state != AppState::Attached || m.selected < 0) return;
    if (std::strcmp(kGames[m.selected].displayName, "Beasts of Bermuda") != 0)
        return;
    if (!m.bob.pawn) return;

    const double nowS =
        std::chrono::duration<double>(
            std::chrono::steady_clock::now().time_since_epoch()).count();

    // ~40 Hz observer is enough to resolve the much slower resource/stat
    // updates without turning this diagnostic into another high-rate IO path.
    if (nowS - g_bobTickLab.lastPollS < 0.025) return;
    g_bobTickLab.lastPollS = nowS;

    if (g_bobTickLab.pawn != m.bob.pawn) {
        g_bobTickLab.pawn = m.bob.pawn;
        g_bobTickLab.compStats = 0;
        BobTickLabResetMetrics();
        g_bobTickLab.status = "New pawn detected; captured fresh tick fields";
    }

    BobTickLabCapturePawnFields(m);

    uint64_t comp = 0;
    m.reader.ReadBytes(m.bob.pawn + bob::kOff_BC_CompStats,
                       &comp, sizeof(comp));
    if (comp < 0x10000ULL || comp >= 0x00007FFF00000000ULL) {
        g_bobTickLab.status = "Comp_Stats unavailable";
        return;
    }
    g_bobTickLab.compStats = comp;

    float food = 0, water = 0, growth = 0, injury = 0, health = 0;
    m.reader.ReadBytes(comp + bob::kOff_Stats_Food,   &food,   sizeof(float));
    m.reader.ReadBytes(comp + bob::kOff_Stats_Water,  &water,  sizeof(float));
    m.reader.ReadBytes(comp + bob::kOff_Stats_Growth, &growth, sizeof(float));
    m.reader.ReadBytes(comp + bob::kOff_Stats_Injury, &injury, sizeof(float));
    m.reader.ReadBytes(comp + bob::kOff_Stats_Health, &health, sizeof(float));

    BobTickMetricObserve(g_bobTickLab.food,   food,   nowS);
    BobTickMetricObserve(g_bobTickLab.water,  water,  nowS);
    BobTickMetricObserve(g_bobTickLab.growth, growth, nowS);
    BobTickMetricObserve(g_bobTickLab.injury, injury, nowS);
    BobTickMetricObserve(g_bobTickLab.health, health, nowS);
}



static std::string g_bobF7RestoreStatus = "F7: restore talents + range (+ DryTickSpeed if changed)";
static std::chrono::steady_clock::time_point g_bobF7RestoreStatusUntil{};

// ADeityShrineBase::SERVER_BlessPlayer(ACharacter* CharRef, float TimeSeconds)
// (Net, NetReliable, Native, Event, NetServer, NetValidate)
// Param struct: 0x10 bytes — CharRef (8) at +0x00, TimeSeconds (4) at +0x08, pad.
//
// Server-side flow at a real shrine: the calling client must be physically
// next to a shrine, then UBBTrialsLibrary::BlessPlayer(shrine, sacrificeType,
// time) dispatches the SERVER_ RPC on that shrine actor.  Our path skips the
// proximity-UI and just dispatches directly on any DeityShrine instance the
// client has in GObjects.  _Validate may reject if the caller isn't near
// the shrine — that's the gameplay gate worth probing.  Sacrifice cost is
// hidden inside _Implementation; if it's not enforced for "self-bless," any
// duration we pass goes through.
// Locates the CDO of UBBCharacterLibrary in GObjects.  The static
// library function BlessPlayer(charRef, sacType, timeSeconds) is what
// the in-game UI invokes — it lives on the CDO and ProcessEvent on it
// handles the static dispatch, no shrine actor required.  Empirically
// confirmed: shrine actors are server-only on this BoB build (clients
// never see DeityShrine_C in GObjects), but the library function
// itself has full client-side reachability through the CDO.
//
// `outDiag` (optional) collects any class name containing "Library" or
// "BBCharacter" plus its CDO presence — so when the exact match fails
// we can see what BoB actually exposes at runtime and adjust the match.
static uint64_t BobFindBBCharacterLibraryCDO(AppModel& m, const GameConfig& g,
                                             std::string* outDiag = nullptr)
{
    if (!m.mainBase || !g.gObjectsRva || !g.gNamesRva) return 0;
    uint64_t gobj = m.mainBase + g.gObjectsRva;
    uint64_t fnp  = m.mainBase + g.gNamesRva;
    uint64_t chunksArr = m.reader.Read<uint64_t>(gobj + 0x00);
    int32_t  numChunks = m.reader.Read<int32_t>(gobj + 0x1C);
    if (!chunksArr || numChunks <= 0 || numChunks > 1024) return 0;

    constexpr size_t chunkBytes =
        (size_t)bob::kObjectsPerChunk * bob::kFUObjectItemSize;
    // 64 KB strips — 24 reads per chunk, well under any plausible IOCTL
    // truncation cap.  Bigger 256 KB strips were apparently still being
    // truncated by the driver; this is conservative.
    constexpr size_t kStrip = 64 * 1024;
    std::vector<uint8_t> chunkBuf(chunkBytes, 0);

    int objsScanned = 0;
    int chunksWalked = 0;
    uint64_t exactMatch = 0;        // className == "BBCharacterLibrary" CDO
    uint64_t looseMatch = 0;        // className contains "BBCharacter" CDO
    uint64_t libraryMatch = 0;      // className contains "Library" CDO
    std::unordered_map<std::string, int> diagCounts;

    for (int32_t ch = 0; ch < numChunks; ++ch) {
        uint64_t chunk = m.reader.Read<uint64_t>(chunksArr + (uint64_t)ch * 8);
        if (!chunk) continue;
        std::fill(chunkBuf.begin(), chunkBuf.end(), 0);
        for (size_t off = 0; off < chunkBytes; off += kStrip) {
            size_t want = (chunkBytes - off > kStrip) ? kStrip : (chunkBytes - off);
            m.reader.ReadBytes(chunk + off, chunkBuf.data() + off, want);
        }
        ++chunksWalked;
        for (int32_t ix = 0; ix < (int32_t)bob::kObjectsPerChunk; ++ix) {
            uint64_t obj = 0;
            std::memcpy(&obj,
                chunkBuf.data() + (size_t)ix * bob::kFUObjectItemSize, 8);
            if (!obj) continue;
            uint64_t cp = m.reader.Read<uint64_t>(obj + bob::kOff_UObject_Class);
            if (!cp) continue;
            ++objsScanned;
            uint32_t classFn = m.reader.Read<uint32_t>(cp + bob::kOff_UObject_Name);
            std::string className = BobResolveFName(m.reader, fnp, classFn);
            // Cheap pre-filter: only consider classes named like a library.
            if (className.find("Library") == std::string::npos &&
                className.find("BBCharacter") == std::string::npos)
                continue;

            uint32_t fnObj = m.reader.Read<uint32_t>(obj + bob::kOff_UObject_Name);
            std::string objName = BobResolveFName(m.reader, fnp, fnObj);
            bool isCdo = (objName.rfind("Default__", 0) == 0);
            // Track candidates seen, both CDO and not, for the diagnostic.
            std::string key = className + (isCdo ? " [CDO]" : "");
            diagCounts[key]++;

            // Prefer:  exact "BBCharacterLibrary" CDO  >  any "BBCharacter*" CDO
            //                                          >  any "*Library" CDO
            if (!isCdo) continue;
            if (className == "BBCharacterLibrary" && !exactMatch)
                exactMatch = obj;
            else if (className.find("BBCharacter") != std::string::npos && !looseMatch)
                looseMatch = obj;
            else if (className.find("Library") != std::string::npos && !libraryMatch)
                libraryMatch = obj;
        }
    }

    if (outDiag) {
        char hdr[160];
        std::snprintf(hdr, sizeof(hdr),
            "scanned %d obj across %d/%d chunks. ",
            objsScanned, chunksWalked, numChunks);
        outDiag->clear();
        *outDiag = hdr;
        if (diagCounts.empty()) {
            *outDiag += "(no Library/BBCharacter classes found)";
        } else {
            *outDiag += "candidates: ";
            for (auto& [k, v] : diagCounts) {
                char b[160];
                std::snprintf(b, sizeof(b), "%s(%d) ", k.c_str(), v);
                *outDiag += b;
            }
        }
    }

    if (exactMatch)   return exactMatch;
    if (looseMatch)   return looseMatch;
    if (libraryMatch) return libraryMatch;
    return 0;
}


// ============================================================================
// Hybrid AH15.12 - EVENT / DEITY BLESSING TEST HELPERS
//
// SDK-confirmed event status values:
//   81 EVENT_WeatherImmunity
//   82 EVENT_LowFoodWaterDrain
//   83 EVENT_AutoResurrection
//   84 EVENT_AISwarm
//   85 EVENT_Nesting
//   86 EVENT_GrowthBuff
//   87 EVENT_PledgeAmplify
//   88 EVENT_Reskin
//
// The game-facing names "Death's Blessing" and "Blessing of the Deities"
// are not present as literal SDK strings.  The most useful matching runtime
// status candidates are therefore shown with their SDK names:
//   Death's Blessing?          -> EVENT_AutoResurrection (83)
//   Blessing of the Deities?   -> EVENT_PledgeAmplify    (87)
//
// No WorldEvent is spawned by these helpers.
// ============================================================================

static uint64_t BobFindExactClassCDO(
    AppModel& m,
    const GameConfig& g,
    const char* wantedClass,
    std::string* outDiag = nullptr)
{
    if (!wantedClass ||
        !*wantedClass ||
        !m.mainBase ||
        !g.gObjectsRva ||
        !g.gNamesRva) {
        if (outDiag)
            *outDiag = "invalid CDO search inputs";
        return 0;
    }

    const uint64_t gobj =
        m.mainBase + g.gObjectsRva;

    const uint64_t fnp =
        m.mainBase + g.gNamesRva;

    const uint64_t chunksArr =
        m.reader.Read<uint64_t>(
            gobj + 0x00);

    const int32_t numChunks =
        m.reader.Read<int32_t>(
            gobj + 0x1C);

    if (!chunksArr ||
        numChunks <= 0 ||
        numChunks > 1024) {
        if (outDiag)
            *outDiag = "GObjects chunk layout unavailable";
        return 0;
    }

    constexpr size_t chunkBytes =
        (size_t)bob::kObjectsPerChunk *
        bob::kFUObjectItemSize;

    constexpr size_t kStrip =
        64 * 1024;

    std::vector<uint8_t> chunkBuf(
        chunkBytes,
        0);

    int objectsScanned = 0;
    int classMatches = 0;

    for (int32_t ch = 0;
         ch < numChunks;
         ++ch) {

        const uint64_t chunk =
            m.reader.Read<uint64_t>(
                chunksArr +
                (uint64_t)ch * 8);

        if (!chunk)
            continue;

        std::fill(
            chunkBuf.begin(),
            chunkBuf.end(),
            0);

        for (size_t off = 0;
             off < chunkBytes;
             off += kStrip) {

            const size_t want =
                (chunkBytes - off > kStrip)
                    ? kStrip
                    : (chunkBytes - off);

            m.reader.ReadBytes(
                chunk + off,
                chunkBuf.data() + off,
                want);
        }

        for (int32_t ix = 0;
             ix < (int32_t)bob::kObjectsPerChunk;
             ++ix) {

            uint64_t obj = 0;

            std::memcpy(
                &obj,
                chunkBuf.data() +
                    (size_t)ix *
                    bob::kFUObjectItemSize,
                8);

            if (!obj)
                continue;

            ++objectsScanned;

            const uint64_t cp =
                m.reader.Read<uint64_t>(
                    obj +
                    bob::kOff_UObject_Class);

            if (!cp)
                continue;

            const uint32_t classFn =
                m.reader.Read<uint32_t>(
                    cp +
                    bob::kOff_UObject_Name);

            const std::string className =
                BobResolveFName(
                    m.reader,
                    fnp,
                    classFn);

            if (className != wantedClass)
                continue;

            ++classMatches;

            const uint32_t objFn =
                m.reader.Read<uint32_t>(
                    obj +
                    bob::kOff_UObject_Name);

            const std::string objName =
                BobResolveFName(
                    m.reader,
                    fnp,
                    objFn);

            if (objName.rfind(
                    "Default__",
                    0) != 0) {
                continue;
            }

            if (outDiag) {
                char b[256];
                std::snprintf(
                    b,
                    sizeof(b),
                    "found %s CDO @ 0x%llX after %d objects",
                    wantedClass,
                    (unsigned long long)obj,
                    objectsScanned);
                *outDiag = b;
            }

            return obj;
        }
    }

    if (outDiag) {
        char b[256];
        std::snprintf(
            b,
            sizeof(b),
            "no %s CDO; objects=%d classMatches=%d",
            wantedClass,
            objectsScanned,
            classMatches);
        *outDiag = b;
    }

    return 0;
}

struct BobEventStatusReadback {
    bool functionOk = false;
    bool active = false;

    bool remainingOk = false;
    float remainingSeconds = 0.0f;

    bool serverFlagOk = false;
    bool setOnServerReplicateToClient = false;

    std::string status;
};

static bool BobGetEventStatusActive(
    AppModel& m,
    const GameConfig& g,
    uint8_t condition,
    bool& outActive,
    std::string& status)
{
    outActive = false;

    if (!m.bob.pawn) {
        status = "BoB pawn unresolved";
        return false;
    }

    std::string cdoDiag;
    const uint64_t cdo =
        BobFindExactClassCDO(
            m,
            g,
            "BBStatusLibrary",
            &cdoDiag);

    if (!cdo) {
        status =
            "BBStatusLibrary CDO not found: " +
            cdoDiag;
        return false;
    }

    // BBStatusLibrary_GetHasStatusConditionApplied
    // sizeof = 0x10
    //   +0x00 ACharacter* CharRef
    //   +0x08 EStatusCondition
    //   +0x09 bool ReturnValue
    std::vector<uint8_t> parms(
        0x10,
        0);

    const uint64_t pawn =
        m.bob.pawn;

    std::memcpy(
        parms.data() + 0x00,
        &pawn,
        8);

    parms[0x08] =
        condition;

    std::vector<std::pair<size_t, FStringArg>>
        noFx;

    std::vector<uint8_t> after;

    if (!InvokeRpc(
            m,
            g,
            cdo,
            { "BBStatusLibrary" },
            "GetHasStatusConditionApplied",
            parms,
            noFx,
            status,
            0,
            &after)) {
        return false;
    }

    if (after.size() < 0x0A) {
        status =
            "GetHasStatusConditionApplied returned short parms";
        return false;
    }

    outActive =
        after[0x09] != 0;

    status =
        outActive
            ? "status active"
            : "status not active";

    return true;
}

static bool BobGetEventStatusRemaining(
    AppModel& m,
    const GameConfig& g,
    uint8_t condition,
    float& outSeconds,
    std::string& status)
{
    outSeconds = 0.0f;

    if (!m.bob.pawn) {
        status = "BoB pawn unresolved";
        return false;
    }

    std::string cdoDiag;
    const uint64_t cdo =
        BobFindExactClassCDO(
            m,
            g,
            "BBStatusLibrary",
            &cdoDiag);

    if (!cdo) {
        status =
            "BBStatusLibrary CDO not found: " +
            cdoDiag;
        return false;
    }

    // BBStatusLibrary_GetTimeUntilStatusConditionExpires
    // sizeof = 0x10
    //   +0x00 ACharacter* CharRef
    //   +0x08 EStatusCondition
    //   +0x0C float ReturnValue
    std::vector<uint8_t> parms(
        0x10,
        0);

    const uint64_t pawn =
        m.bob.pawn;

    std::memcpy(
        parms.data() + 0x00,
        &pawn,
        8);

    parms[0x08] =
        condition;

    std::vector<std::pair<size_t, FStringArg>>
        noFx;

    std::vector<uint8_t> after;

    if (!InvokeRpc(
            m,
            g,
            cdo,
            { "BBStatusLibrary" },
            "GetTimeUntilStatusConditionExpires",
            parms,
            noFx,
            status,
            0,
            &after)) {
        return false;
    }

    if (after.size() < 0x10) {
        status =
            "GetTimeUntilStatusConditionExpires returned short parms";
        return false;
    }

    std::memcpy(
        &outSeconds,
        after.data() + 0x0C,
        4);

    if (!std::isfinite(outSeconds) ||
        std::fabs(outSeconds) >
            1000000000.0f) {
        status =
            "remaining time readback implausible";
        return false;
    }

    status =
        "remaining time read";

    return true;
}

static bool BobGetEventStatusServerFlag(
    AppModel& m,
    const GameConfig& g,
    uint8_t condition,
    bool& outServerReplicated,
    std::string& status)
{
    outServerReplicated = false;

    if (!m.bob.pawn) {
        status = "BoB pawn unresolved";
        return false;
    }

    std::string cdoDiag;
    const uint64_t cdo =
        BobFindExactClassCDO(
            m,
            g,
            "BBStatusLibrary",
            &cdoDiag);

    if (!cdo) {
        status =
            "BBStatusLibrary CDO not found: " +
            cdoDiag;
        return false;
    }

    // BBStatusLibrary_GetSetOnServerReplicateToClient
    // sizeof = 0x10
    //   +0x00 AActor* WorldContext
    //   +0x08 EStatusCondition
    //   +0x09 bool ReturnValue
    std::vector<uint8_t> parms(
        0x10,
        0);

    const uint64_t worldContext =
        m.bob.pawn;

    std::memcpy(
        parms.data() + 0x00,
        &worldContext,
        8);

    parms[0x08] =
        condition;

    std::vector<std::pair<size_t, FStringArg>>
        noFx;

    std::vector<uint8_t> after;

    if (!InvokeRpc(
            m,
            g,
            cdo,
            { "BBStatusLibrary" },
            "GetSetOnServerReplicateToClient",
            parms,
            noFx,
            status,
            0,
            &after)) {
        return false;
    }

    if (after.size() < 0x0A) {
        status =
            "GetSetOnServerReplicateToClient returned short parms";
        return false;
    }

    outServerReplicated =
        after[0x09] != 0;

    status =
        outServerReplicated
            ? "SDK marks this status server->client replicated"
            : "SDK does not mark this status server->client replicated";

    return true;
}

static BobEventStatusReadback BobReadEventStatus(
    AppModel& m,
    const GameConfig& g,
    uint8_t condition)
{
    BobEventStatusReadback out;

    std::string activeStatus;
    out.functionOk =
        BobGetEventStatusActive(
            m,
            g,
            condition,
            out.active,
            activeStatus);

    std::string remainStatus;
    out.remainingOk =
        BobGetEventStatusRemaining(
            m,
            g,
            condition,
            out.remainingSeconds,
            remainStatus);

    std::string flagStatus;
    out.serverFlagOk =
        BobGetEventStatusServerFlag(
            m,
            g,
            condition,
            out.setOnServerReplicateToClient,
            flagStatus);

    std::ostringstream oss;

    oss
        << "status=" << (unsigned)condition
        << " active="
        << (out.functionOk
                ? (out.active ? "YES" : "NO")
                : "?");

    if (out.remainingOk) {
        oss
            << " remaining="
            << std::fixed
            << std::setprecision(1)
            << out.remainingSeconds
            << "s";
    } else {
        oss
            << " remaining=?";
    }

    if (out.serverFlagOk) {
        oss
            << " serverReplicated="
            << (out.setOnServerReplicateToClient
                    ? "YES"
                    : "NO");
    } else {
        oss
            << " serverReplicated=?";
    }

    if (!out.functionOk) {
        oss
            << " | activeErr="
            << activeStatus;
    }

    out.status =
        oss.str();

    return out;
}

static bool BobApplyEventStatusLocal(
    AppModel& m,
    const GameConfig& g,
    uint8_t condition,
    float durationSeconds,
    BobEventStatusReadback& outReadback,
    std::string& status)
{
    if (!m.bob.pawn) {
        status =
            "BoB pawn unresolved";
        return false;
    }

    if (!std::isfinite(durationSeconds) ||
        durationSeconds < 1.0f ||
        durationSeconds >
            7200000.0f) {
        status =
            "Event duration must be 1..7,200,000 seconds";
        return false;
    }

    std::string cdoDiag;
    const uint64_t cdo =
        BobFindExactClassCDO(
            m,
            g,
            "BBStatusLibrary",
            &cdoDiag);

    if (!cdo) {
        status =
            "BBStatusLibrary CDO not found: " +
            cdoDiag;
        return false;
    }

    // BBStatusLibrary_ApplyStatusCondition_NoDelegates
    // sizeof = 0x20
    //   +0x00 ACharacter* InstigatorRef
    //   +0x08 ACharacter* TargetCharRef
    //   +0x10 EStatusCondition
    //   +0x14 float Duration
    //   +0x18 bool ReturnValue
    std::vector<uint8_t> parms(
        0x20,
        0);

    const uint64_t pawn =
        m.bob.pawn;

    std::memcpy(
        parms.data() + 0x00,
        &pawn,
        8);

    std::memcpy(
        parms.data() + 0x08,
        &pawn,
        8);

    parms[0x10] =
        condition;

    std::memcpy(
        parms.data() + 0x14,
        &durationSeconds,
        4);

    std::vector<std::pair<size_t, FStringArg>>
        noFx;

    std::vector<uint8_t> after;

    std::string invokeStatus;

    const bool invoked =
        InvokeRpc(
            m,
            g,
            cdo,
            { "BBStatusLibrary" },
            "ApplyStatusCondition_NoDelegates",
            parms,
            noFx,
            invokeStatus,
            0,
            &after);

    if (!invoked) {
        status =
            "ApplyStatusCondition_NoDelegates failed: " +
            invokeStatus;
        return false;
    }

    bool functionReturn = false;

    if (after.size() >= 0x19) {
        functionReturn =
            after[0x18] != 0;
    }

    // Read back through the game's own status helpers so we can distinguish
    // "function invoked" from "status actually appears active on this client".
    outReadback =
        BobReadEventStatus(
            m,
            g,
            condition);

    std::ostringstream oss;

    oss
        << "Apply status "
        << (unsigned)condition
        << " return="
        << (functionReturn ? "TRUE" : "FALSE")
        << " | "
        << outReadback.status;

    status =
        oss.str();

    return functionReturn &&
           outReadback.functionOk &&
           outReadback.active;
}

static bool BobRemoveEventStatusLocal(
    AppModel& m,
    const GameConfig& g,
    uint8_t condition,
    BobEventStatusReadback& outReadback,
    std::string& status)
{
    if (!m.bob.pawn) {
        status =
            "BoB pawn unresolved";
        return false;
    }

    std::string cdoDiag;
    const uint64_t cdo =
        BobFindExactClassCDO(
            m,
            g,
            "BBStatusLibrary",
            &cdoDiag);

    if (!cdo) {
        status =
            "BBStatusLibrary CDO not found: " +
            cdoDiag;
        return false;
    }

    // BBStatusLibrary_RemoveStatusCondition
    // sizeof = 0x18
    //   +0x00 ACharacter* TargetCharRef
    //   +0x08 EStatusCondition
    //   +0x0C int32 NumStacks
    //   +0x10 bool ReturnValue
    std::vector<uint8_t> parms(
        0x18,
        0);

    const uint64_t pawn =
        m.bob.pawn;

    const int32_t numStacks =
        99;

    std::memcpy(
        parms.data() + 0x00,
        &pawn,
        8);

    parms[0x08] =
        condition;

    std::memcpy(
        parms.data() + 0x0C,
        &numStacks,
        4);

    std::vector<std::pair<size_t, FStringArg>>
        noFx;

    std::vector<uint8_t> after;

    std::string invokeStatus;

    if (!InvokeRpc(
            m,
            g,
            cdo,
            { "BBStatusLibrary" },
            "RemoveStatusCondition",
            parms,
            noFx,
            invokeStatus,
            0,
            &after)) {
        status =
            "RemoveStatusCondition failed: " +
            invokeStatus;
        return false;
    }

    const bool functionReturn =
        after.size() >= 0x11 &&
        after[0x10] != 0;

    outReadback =
        BobReadEventStatus(
            m,
            g,
            condition);

    std::ostringstream oss;

    oss
        << "Remove status "
        << (unsigned)condition
        << " return="
        << (functionReturn ? "TRUE" : "FALSE")
        << " | "
        << outReadback.status;

    status =
        oss.str();

    return functionReturn;
}

static bool BobBlessSelfViaCharacterLibrary(
    AppModel& m,
    const GameConfig& g,
    uint8_t trialCategory,
    float durationSeconds,
    std::string& status)
{
    if (!m.bob.pawn) {
        status =
            "BoB pawn unresolved";
        return false;
    }

    if (trialCategory < 1 ||
        trialCategory > 4) {
        status =
            "Trial category must be 1..4";
        return false;
    }

    if (!std::isfinite(durationSeconds) ||
        durationSeconds < 1.0f ||
        durationSeconds >
            7200000.0f) {
        status =
            "Bless duration must be 1..7,200,000 seconds";
        return false;
    }

    std::string cdoDiag;
    const uint64_t cdo =
        BobFindBBCharacterLibraryCDO(
            m,
            g,
            &cdoDiag);

    if (!cdo) {
        status =
            "BBCharacterLibrary CDO not found: " +
            cdoDiag;
        return false;
    }

    // BBCharacterLibrary_BlessPlayer
    // sizeof = 0x10
    //   +0x00 ACharacter* CharacterRef
    //   +0x08 ETrialCategory SacrificeType
    //   +0x0C float TimeSeconds
    std::vector<uint8_t> parms(
        0x10,
        0);

    const uint64_t pawn =
        m.bob.pawn;

    std::memcpy(
        parms.data() + 0x00,
        &pawn,
        8);

    parms[0x08] =
        trialCategory;

    std::memcpy(
        parms.data() + 0x0C,
        &durationSeconds,
        4);

    std::vector<std::pair<size_t, FStringArg>>
        noFx;

    std::string invokeStatus;

    if (!InvokeRpc(
            m,
            g,
            cdo,
            { "BBCharacterLibrary" },
            "BlessPlayer",
            parms,
            noFx,
            invokeStatus)) {
        status =
            "BBCharacterLibrary::BlessPlayer failed: " +
            invokeStatus;
        return false;
    }

    const char* names[5] = {
        "None",
        "Power",
        "Mobility",
        "Survival",
        "Death"
    };

    char b[320];
    std::snprintf(
        b,
        sizeof(b),
        "BlessPlayer(%s, %.0fs) invoked through BBCharacterLibrary CDO. "
        "Use the event/status readback below to see what became active.",
        names[trialCategory],
        durationSeconds);

    status = b;
    return true;
}

// Legacy stub — older code path used a shrine actor.  Kept defined so
// the previously-saved cache field doesn't dangle, but unused by the
// active bless flow.
static uint64_t BobFindDeityShrine(AppModel& m, const GameConfig& g,
                                   std::string* outCandidates = nullptr)
{
    if (m.bob.deityShrine) return m.bob.deityShrine;
    if (!m.mainBase || !g.gObjectsRva || !g.gNamesRva) return 0;

    uint64_t gobj = m.mainBase + g.gObjectsRva;
    uint64_t fnp  = m.mainBase + g.gNamesRva;

    // Layout B (inner FChunkedFixedUObjectArray) — confirmed for BoB.
    uint64_t chunksArr = m.reader.Read<uint64_t>(gobj + 0x00);
    int32_t  numChunks = m.reader.Read<int32_t>(gobj + 0x1C);
    if (!chunksArr || numChunks <= 0 || numChunks > 1024) return 0;

    std::unordered_map<uint64_t, std::string> cnCache;
    auto ClassNameOf = [&](uint64_t cp) -> const std::string& {
        auto it = cnCache.find(cp);
        if (it != cnCache.end()) return it->second;
        uint32_t fn = m.reader.Read<uint32_t>(cp + bob::kOff_UObject_Name);
        std::string s = BobResolveFName(m.reader, fnp, fn);
        auto [ins, _] = cnCache.emplace(cp, std::move(s));
        return ins->second;
    };

    // Score each candidate class so we prefer a likely deity-shrine over
    // a possess-shrine / trinket / shrine-water.  Higher = more likely.
    auto Score = [](const std::string& cn) -> int {
        // Disqualifiers — these are confirmed-not-the-bless-RPC class
        // families.  Returning a very negative score means "never pick".
        if (cn.find("Water")   != std::string::npos) return -100;
        if (cn.find("Fresh")   != std::string::npos) return -100;
        if (cn.find("Trinket") != std::string::npos) return -100;
        if (cn.find("Possess") != std::string::npos) return -100;
        // Anything else containing "Shrine" or "Deity" is a candidate.
        // Boost the score for known good substrings so the most-likely
        // class wins ties.
        int score = 0;
        if (cn.find("Shrine")     != std::string::npos) score += 10;
        if (cn.find("Deity")      != std::string::npos) score += 50;
        if (cn.find("DeityShrine")!= std::string::npos) score += 100;
        if (cn.find("Bless")      != std::string::npos) score += 30;
        return score > 0 ? score : -1;
    };

    // class -> live count for the diagnostic
    std::unordered_map<std::string, int> shrineClassCounts;
    uint64_t bestObj      = 0;
    int      bestScore    = 0;
    int      objsScanned  = 0;
    int      chunksWalked = 0;

    // Bulk-read each chunk in 256 KB slices.  A single 1.5 MB IOCTL gets
    // truncated by the driver (we observed exactly that — only the first
    // ~1 MB is filled, leaving the tail zero so half the slots look
    // null).  256 KB is small enough to always succeed and we just stitch
    // the strips together into one buffer.
    constexpr size_t chunkBytes =
        (size_t)bob::kObjectsPerChunk * bob::kFUObjectItemSize;
    constexpr size_t kStrip = 256 * 1024;
    std::vector<uint8_t> chunkBuf;
    chunkBuf.resize(chunkBytes);

    for (int32_t ch = 0; ch < numChunks; ++ch) {
        uint64_t chunk = m.reader.Read<uint64_t>(chunksArr + (uint64_t)ch * 8);
        if (!chunk) continue;
        std::fill(chunkBuf.begin(), chunkBuf.end(), 0);
        for (size_t off = 0; off < chunkBytes; off += kStrip) {
            size_t want = (chunkBytes - off > kStrip) ? kStrip : (chunkBytes - off);
            m.reader.ReadBytes(chunk + off, chunkBuf.data() + off, want);
        }
        ++chunksWalked;

        for (int32_t ix = 0; ix < (int32_t)bob::kObjectsPerChunk; ++ix) {
            uint64_t obj = 0;
            std::memcpy(&obj,
                chunkBuf.data() + (size_t)ix * bob::kFUObjectItemSize, 8);
            if (!obj) continue;
            uint64_t cp = m.reader.Read<uint64_t>(obj + bob::kOff_UObject_Class);
            if (!cp) continue;
            ++objsScanned;
            const std::string& cn = ClassNameOf(cp);
            int sc = Score(cn);
            if (sc <= 0) continue;
            // Skip CDOs.
            uint32_t fnObj = m.reader.Read<uint32_t>(obj + bob::kOff_UObject_Name);
            std::string objName = BobResolveFName(m.reader, fnp, fnObj);
            if (objName.rfind("Default__", 0) == 0) continue;
            shrineClassCounts[cn]++;
            if (sc > bestScore) {
                bestScore = sc;
                bestObj   = obj;
            }
        }
    }

    if (outCandidates) {
        char hdr[160];
        std::snprintf(hdr, sizeof(hdr),
            "scanned %d obj across %d/%d chunks. shrine-classes: ",
            objsScanned, chunksWalked, numChunks);
        outCandidates->clear();
        *outCandidates = hdr;
        if (shrineClassCounts.empty()) {
            *outCandidates += "(none)";
        } else {
            for (auto& [k, v] : shrineClassCounts) {
                char b[160];
                std::snprintf(b, sizeof(b), "%s (%d) ", k.c_str(), v);
                *outCandidates += b;
            }
        }
    }

    if (bestObj) m.bob.deityShrine = bestObj;
    return bestObj;
}

// UBBCharacterLibrary::BlessPlayer(ACharacter* CharacterRef,
//                                  ETrialCategory SacrificeType,
//                                  float TimeSeconds)
// Static native library function.  Param struct = 0x10 bytes:
//   +0x00  ACharacter* CharacterRef   (pawn pointer)
//   +0x08  uint8       SacrificeType  (1=Power, 2=Mobility, 3=Survival)
//   +0x09  uint8 pad x3
//   +0x0C  float       TimeSeconds
//
// Dispatches on the BBCharacterLibrary CDO — the SDK's own wrapper
// uses GetDefaultObj()->ProcessEvent for this exact reason.  No shrine
// actor required.
// Walk GObjects looking for a UObject whose own FName matches `funcName`
// AND whose CLASS is "Function" (UE's runtime class for UFunction
// objects).  Each UFunction is its own UObject in GObjects; its Outer
// pointer is the owning UClass.  Return both the function VA and the
// outer-class VA so the caller can pick a thisObj of that class.
struct BobFunctionFind {
    uint64_t funcVa     = 0;
    uint64_t outerClass = 0;
    std::string outerName;
};
static BobFunctionFind BobFindUFunctionByName(AppModel& m, const GameConfig& g,
                                              const char* funcName,
                                              std::string* outDiag = nullptr)
{
    BobFunctionFind out;
    if (!m.mainBase || !g.gObjectsRva || !g.gNamesRva) return out;
    uint64_t gobj = m.mainBase + g.gObjectsRva;
    uint64_t fnp  = m.mainBase + g.gNamesRva;
    uint64_t chunksArr = m.reader.Read<uint64_t>(gobj + 0x00);
    int32_t  numChunks = m.reader.Read<int32_t>(gobj + 0x1C);
    if (!chunksArr || numChunks <= 0 || numChunks > 1024) return out;

    constexpr size_t chunkBytes =
        (size_t)bob::kObjectsPerChunk * bob::kFUObjectItemSize;
    constexpr size_t kStrip = 64 * 1024;
    std::vector<uint8_t> chunkBuf(chunkBytes, 0);

    int objsScanned = 0;
    int candidatesFound = 0;
    std::string targetName(funcName);

    for (int32_t ch = 0; ch < numChunks; ++ch) {
        uint64_t chunk = m.reader.Read<uint64_t>(chunksArr + (uint64_t)ch * 8);
        if (!chunk) continue;
        std::fill(chunkBuf.begin(), chunkBuf.end(), 0);
        for (size_t off = 0; off < chunkBytes; off += kStrip) {
            size_t want = (chunkBytes - off > kStrip) ? kStrip : (chunkBytes - off);
            m.reader.ReadBytes(chunk + off, chunkBuf.data() + off, want);
        }
        for (int32_t ix = 0; ix < (int32_t)bob::kObjectsPerChunk; ++ix) {
            uint64_t obj = 0;
            std::memcpy(&obj,
                chunkBuf.data() + (size_t)ix * bob::kFUObjectItemSize, 8);
            if (!obj) continue;
            ++objsScanned;
            // Cheap pre-check: object's own FName.  Most UObjects aren't
            // named "BlessPlayer", so this skips fast.
            uint32_t fnObj = m.reader.Read<uint32_t>(obj + bob::kOff_UObject_Name);
            std::string objName = BobResolveFName(m.reader, fnp, fnObj);
            if (objName != targetName) continue;
            ++candidatesFound;

            // Confirm this is a UFunction (class FName == "Function").
            uint64_t cp = m.reader.Read<uint64_t>(obj + bob::kOff_UObject_Class);
            if (!cp) continue;
            uint32_t classFn = m.reader.Read<uint32_t>(cp + bob::kOff_UObject_Name);
            std::string className = BobResolveFName(m.reader, fnp, classFn);
            if (className != "Function") continue;

            // Outer is the UClass that owns this UFunction.
            uint64_t outer = 0;
            m.reader.ReadBytes(obj + bob::kOff_UObject_Outer, &outer, 8);
            if (!outer) continue;
            uint32_t outerFn = m.reader.Read<uint32_t>(outer + bob::kOff_UObject_Name);
            std::string outerName = BobResolveFName(m.reader, fnp, outerFn);

            out.funcVa     = obj;
            out.outerClass = outer;
            out.outerName  = outerName;
            if (outDiag) {
                char b[256];
                std::snprintf(b, sizeof(b),
                    "found UFunction %s @ %llX  outer=%s @ %llX",
                    funcName, (unsigned long long)obj,
                    outerName.c_str(), (unsigned long long)outer);
                *outDiag = b;
            }
            return out;
        }
    }
    if (outDiag) {
        char b[256];
        std::snprintf(b, sizeof(b),
            "scanned %d obj, %d named '%s' but none was a UFunction",
            objsScanned, candidatesFound, funcName);
        *outDiag = b;
    }
    return out;
}

// Hybrid S: enumerate EVERY loaded UFunction with a given name rather than
// returning the first one.  This matters for Blueprint functions such as
// CheckPlayerCanDoAttack1 because many playable species can own a function
// with the same short name.
static std::vector<BobFunctionFind> BobFindUFunctionsByNameAll(
    AppModel& m, const GameConfig& g, const char* funcName,
    std::string* outDiag = nullptr)
{
    std::vector<BobFunctionFind> out;
    if (!m.mainBase || !g.gObjectsRva || !g.gNamesRva || !funcName || !*funcName)
        return out;

    const uint64_t gobj = m.mainBase + g.gObjectsRva;
    const uint64_t fnp  = m.mainBase + g.gNamesRva;
    const uint64_t chunksArr = m.reader.Read<uint64_t>(gobj + 0x00);
    const int32_t numChunks  = m.reader.Read<int32_t>(gobj + 0x1C);
    if (!chunksArr || numChunks <= 0 || numChunks > 1024)
        return out;

    constexpr size_t chunkBytes =
        (size_t)bob::kObjectsPerChunk * bob::kFUObjectItemSize;
    constexpr size_t kStrip = 64 * 1024;
    std::vector<uint8_t> chunkBuf(chunkBytes, 0);

    int objsScanned = 0;
    int nameMatches = 0;
    const std::string targetName(funcName);

    for (int32_t ch = 0; ch < numChunks; ++ch) {
        const uint64_t chunk =
            m.reader.Read<uint64_t>(chunksArr + (uint64_t)ch * 8);
        if (!chunk) continue;

        std::fill(chunkBuf.begin(), chunkBuf.end(), 0);
        for (size_t off = 0; off < chunkBytes; off += kStrip) {
            const size_t want =
                (chunkBytes - off > kStrip) ? kStrip : (chunkBytes - off);
            m.reader.ReadBytes(chunk + off, chunkBuf.data() + off, want);
        }

        for (int32_t ix = 0; ix < (int32_t)bob::kObjectsPerChunk; ++ix) {
            uint64_t obj = 0;
            std::memcpy(&obj,
                chunkBuf.data() + (size_t)ix * bob::kFUObjectItemSize, 8);
            if (!obj) continue;
            ++objsScanned;

            const uint32_t fnObj =
                m.reader.Read<uint32_t>(obj + bob::kOff_UObject_Name);
            const std::string objName =
                BobResolveFName(m.reader, fnp, fnObj);
            if (objName != targetName) continue;
            ++nameMatches;

            const uint64_t cp =
                m.reader.Read<uint64_t>(obj + bob::kOff_UObject_Class);
            if (!cp) continue;
            const uint32_t classFn =
                m.reader.Read<uint32_t>(cp + bob::kOff_UObject_Name);
            if (BobResolveFName(m.reader, fnp, classFn) != "Function")
                continue;

            uint64_t outer = 0;
            if (m.reader.ReadBytes(obj + bob::kOff_UObject_Outer,
                                   &outer, sizeof(outer)) != sizeof(outer) ||
                !outer)
                continue;

            const uint32_t outerFn =
                m.reader.Read<uint32_t>(outer + bob::kOff_UObject_Name);

            BobFunctionFind f;
            f.funcVa     = obj;
            f.outerClass = outer;
            f.outerName  = BobResolveFName(m.reader, fnp, outerFn);
            out.push_back(std::move(f));
        }
    }

    if (outDiag) {
        char b[320];
        std::snprintf(b, sizeof(b),
            "scanned %d objects; %d named '%s'; %zu UFunctions returned",
            objsScanned, nameMatches, funcName, out.size());
        *outDiag = b;
    }
    return out;
}


// ============================================================================
// Hybrid AH — READ-ONLY carcass food Blueprint tracer.
//
// Goal: identify the loaded Blueprint function that converts a real carcass
// bite into Food_Regenerated(Value).  This scanner NEVER writes target memory.
// It makes one GObjects pass for a small set of eating-related UFunction names,
// reads each candidate's Script TArray, and reports:
//   * owner class + UFunction address
//   * Script TArray offset / address / size
//   * EX_FloatConst values near the measured vanilla path (0.25 / 0.5 / 2.0)
//   * EX_FinalFunction calls whose target name contains "Food"
//
// User-observed vanilla carnivore carcass bite:
//   carcass RemainingFood: -2.0
//   player Food:           +0.5
// so 0.25, 0.5 and 2.0 are high-value trace constants, but this scanner does
// not assume any one of them is the reward multiplier until a caller proves it.
// ============================================================================
struct BobFoodTraceFunction {
    std::string name;
    std::string outerName;
    uint64_t functionVa = 0;
    uint32_t scriptHeaderOffset = 0;
    uint64_t scriptDataVa = 0;
    int32_t scriptSize = 0;
    std::vector<std::pair<size_t, float>> interestingFloats;
    struct FoodCall {
        size_t scriptOffset = 0;
        std::string callKind;
        std::string targetName;
        uint64_t targetFunctionVa = 0;
    };
    std::vector<FoodCall> foodCalls;
};

struct BobFoodTraceState {
    std::string status = "Not scanned";
    std::string report;
    std::vector<BobFoodTraceFunction> functions;
    uint64_t world = 0;
};
static BobFoodTraceState g_bobFoodTrace;

static bool BobReadUFunctionScriptReadOnly(AppModel& m,
                                           uint64_t funcVa,
                                           uint32_t& outHeaderOffset,
                                           uint64_t& outData,
                                           std::vector<uint8_t>& outScript)
{
    outHeaderOffset = 0;
    outData = 0;
    outScript.clear();
    if (!funcVa) return false;

    constexpr uint32_t kTryOffsets[] = {
        0x60, 0x68, 0x70, 0x78, 0x80, 0x88, 0x90, 0x98, 0xA0
    };
    for (uint32_t off : kTryOffsets) {
        uint8_t hdr[16] = {};
        if (m.reader.ReadBytes(funcVa + off, hdr, sizeof(hdr)) != sizeof(hdr))
            continue;

        uint64_t data = 0;
        int32_t num = 0, maxN = 0;
        std::memcpy(&data, hdr, 8);
        std::memcpy(&num, hdr + 8, 4);
        std::memcpy(&maxN, hdr + 12, 4);

        const bool plausible =
            data >= 0x10000ULL && data < 0x7FFF00000000ULL &&
            num > 0 && num <= 262144 && maxN >= num && maxN <= 524288;
        if (!plausible) continue;

        std::vector<uint8_t> script((size_t)num, 0);
        if (m.reader.ReadBytes(data, script.data(), script.size()) != script.size())
            continue;

        // A real Blueprint script normally contains EX_EndOfScript (0x53).
        // Keep this as a sanity check so an unrelated TArray is not reported.
        if (std::find(script.begin(), script.end(), (uint8_t)0x53) == script.end())
            continue;

        outHeaderOffset = off;
        outData = data;
        outScript = std::move(script);
        return true;
    }
    return false;
}

static bool BobResolveUFunctionNameFromPtr(AppModel& m,
                                           const GameConfig& g,
                                           uint64_t ptr,
                                           std::string& outName)
{
    outName.clear();
    if (!ptr || ptr < 0x10000ULL || ptr >= 0x7FFF00000000ULL ||
        !m.mainBase || !g.gNamesRva)
        return false;

    const uint64_t fnp = m.mainBase + g.gNamesRva;
    uint64_t cp = 0;
    if (m.reader.ReadBytes(ptr + bob::kOff_UObject_Class, &cp, sizeof(cp)) != sizeof(cp) || !cp)
        return false;

    uint32_t classFn = 0;
    if (m.reader.ReadBytes(cp + bob::kOff_UObject_Name, &classFn, sizeof(classFn)) != sizeof(classFn))
        return false;
    if (BobResolveFName(m.reader, fnp, classFn) != "Function")
        return false;

    uint32_t nameFn = 0;
    if (m.reader.ReadBytes(ptr + bob::kOff_UObject_Name, &nameFn, sizeof(nameFn)) != sizeof(nameFn))
        return false;
    outName = BobResolveFName(m.reader, fnp, nameFn);
    return !outName.empty();
}

static bool BobFoodTraceNameInteresting(const std::string& s)
{
    if (s.empty()) return false;
    std::string l = s;
    std::transform(l.begin(), l.end(), l.begin(),
        [](unsigned char c) { return (char)std::tolower(c); });
    return l.find("food")    != std::string::npos ||
           l.find("eat")     != std::string::npos ||
           l.find("carcass") != std::string::npos ||
           l.find("meat")    != std::string::npos ||
           l.find("gore")    != std::string::npos ||
           l.find("consume") != std::string::npos;
}

static bool BobFoodTraceResolveFNameInline(AppModel& m,
                                           const GameConfig& g,
                                           const uint8_t* p,
                                           size_t avail,
                                           std::string& out)
{
    out.clear();
    if (!p || avail < 12 || !m.mainBase || !g.gNamesRva) return false;

    // This BoB UE4.26 build stores case-preserving FName bytecode payloads as:
    //   ComparisonIndex (4)
    //   DisplayIndex    (4)
    //   Number          (4)
    //
    // AH13's raw GetTalentMod bytes prove the first argument starts 12 bytes
    // after the function name payload, not 8.  We only need ComparisonIndex
    // to resolve the readable function name.
    uint32_t comparisonIndex = 0;
    std::memcpy(&comparisonIndex, p, 4);
    if (comparisonIndex == 0 || comparisonIndex > 0x10000000u) return false;

    const uint64_t fnp = m.mainBase + g.gNamesRva;
    out = BobResolveFName(m.reader, fnp, comparisonIndex);
    return !out.empty();
}




static std::string BobFoodTraceHexWindow(const std::vector<uint8_t>& script,
                                         size_t begin,
                                         size_t end)
{
    if (begin > script.size()) begin = script.size();
    if (end > script.size()) end = script.size();
    if (end < begin) end = begin;

    static const char* kHex = "0123456789ABCDEF";
    std::string out;
    out.reserve((end - begin) * 3 + 64);

    char hdr[40];
    for (size_t row = begin; row < end; row += 16) {
        std::snprintf(hdr, sizeof(hdr), "    +0x%04zX: ", row);
        out += hdr;
        const size_t rowEnd = std::min(end, row + 16);
        for (size_t i = row; i < rowEnd; ++i) {
            const uint8_t b = script[i];
            out.push_back(kHex[b >> 4]);
            out.push_back(kHex[b & 0xF]);
            out.push_back(' ');
        }
        out.push_back('\n');
    }
    return out;
}


static const char* BobFoodTraceTokenName(uint8_t tok)
{
    switch (tok) {
        case 0x00: return "EX_LocalVariable";
        case 0x01: return "EX_InstanceVariable";
        case 0x0F: return "EX_Let";
        case 0x14: return "EX_LetBool";
        case 0x16: return "EX_EndFunctionParms";
        case 0x17: return "EX_Self";
        case 0x1D: return "EX_IntConst";
        case 0x1E: return "EX_FloatConst";
        case 0x20: return "EX_ObjectConst";
        case 0x21: return "EX_NameConst";
        case 0x24: return "EX_ByteConst";
        case 0x25: return "EX_IntZero";
        case 0x26: return "EX_IntOne";
        case 0x27: return "EX_True";
        case 0x28: return "EX_False";
        case 0x2A: return "EX_NoObject";
        case 0x42: return "EX_StructMemberContext";
        case 0x48: return "EX_LocalOutVariable";
        case 0x64: return "EX_LetValueOnPersistentFrame";
        default:   return "EX_Unknown";
    }
}

static bool BobFoodTraceResolveFieldName(AppModel& m,
                                         const GameConfig& g,
                                         uint64_t fieldPtr,
                                         std::string& outName,
                                         uint32_t& outNameOffset)
{
    outName.clear();
    outNameOffset = 0;
    if (!fieldPtr || fieldPtr < 0x10000ULL ||
        fieldPtr >= 0x7FFF00000000ULL ||
        !m.mainBase || !g.gNamesRva)
        return false;

    const uint64_t fnp = m.mainBase + g.gNamesRva;

    // UE4.25+ FProperty derives from FField. On 64-bit builds FField's
    // FName is normally at +0x20. Keep a few adjacent fallbacks so the
    // diagnostic remains read-only and useful if the exact private layout
    // differs in this build.
    constexpr uint32_t kNameOffsets[] = {
        0x20, 0x18, 0x28, 0x30, 0x38, 0x10
    };

    for (uint32_t off : kNameOffsets) {
        uint32_t idx = 0;
        if (m.reader.ReadBytes(fieldPtr + off, &idx, sizeof(idx)) != sizeof(idx))
            continue;
        if (idx == 0 || idx > 0x10000000u)
            continue;

        std::string s = BobResolveFName(m.reader, fnp, idx);
        if (s.empty() || s == "None")
            continue;

        bool printable = true;
        for (unsigned char ch : s) {
            if (ch < 0x20 || ch > 0x7E) {
                printable = false;
                break;
            }
        }
        if (!printable || s.size() > 160)
            continue;

        outName = std::move(s);
        outNameOffset = off;
        return true;
    }
    return false;
}

struct BobFoodTraceArg {
    std::string paramName;
    size_t exprOffset = 0;
    uint8_t token = 0xFF;
    size_t encodedSize = 0;

    // Direct variable/property expression.
    uint64_t fieldPtr = 0;
    std::string fieldName;
    uint32_t fieldNameOffset = 0;

    // AH8: EX_StructMemberContext = member FProperty* + context expression.
    uint64_t memberFieldPtr = 0;
    std::string memberFieldName;
    uint32_t memberFieldNameOffset = 0;
    uint8_t contextToken = 0xFF;
    uint64_t contextFieldPtr = 0;
    std::string contextFieldName;
    uint32_t contextFieldNameOffset = 0;

    // AH15 constants useful for DataTable / row-name producer calls.
    uint64_t objectPtr = 0;
    std::string objectName;
    std::string nameValue;

    int64_t intValue = 0;
    float floatValue = 0.0f;
};


static bool BobFoodTraceResolveUObjectShortName(
    AppModel& m,
    const GameConfig& g,
    uint64_t objectPtr,
    std::string& outName)
{
    outName.clear();

    if (!objectPtr ||
        objectPtr < 0x10000ULL ||
        objectPtr >= 0x7FFF00000000ULL ||
        !m.mainBase ||
        !g.gNamesRva)
        return false;

    uint32_t fn = 0;
    if (m.reader.ReadBytes(
            objectPtr + bob::kOff_UObject_Name,
            &fn,
            sizeof(fn)) != sizeof(fn))
        return false;

    if (fn == 0 || fn > 0x10000000u)
        return false;

    outName = BobResolveFName(
        m.reader,
        m.mainBase + g.gNamesRva,
        fn);

    return !outName.empty() && outName != "None";
}

static bool BobFoodTraceDecodeSimpleArg(AppModel& m,
                                        const GameConfig& g,
                                        const std::vector<uint8_t>& script,
                                        size_t& pos,
                                        const char* paramName,
                                        BobFoodTraceArg& out)
{
    out = BobFoodTraceArg{};
    out.paramName = paramName ? paramName : "?";
    out.exprOffset = pos;

    if (pos >= script.size())
        return false;

    out.token = script[pos];

    switch (out.token) {
        case 0x00: // EX_LocalVariable -> FProperty*
        case 0x01: // EX_InstanceVariable -> FProperty*
        case 0x48: // EX_LocalOutVariable -> FProperty*
        {
            if (pos + 9 > script.size())
                return false;
            std::memcpy(&out.fieldPtr, script.data() + pos + 1, 8);
            BobFoodTraceResolveFieldName(
                m, g, out.fieldPtr, out.fieldName, out.fieldNameOffset);
            out.encodedSize = 9;
            pos += 9;
            return true;
        }

        case 0x17: // EX_Self
        case 0x25: // EX_IntZero
        case 0x26: // EX_IntOne
        case 0x27: // EX_True
        case 0x28: // EX_False
        case 0x2A: // EX_NoObject
            out.encodedSize = 1;
            pos += 1;
            return true;

        case 0x24: // EX_ByteConst
            if (pos + 2 > script.size())
                return false;
            out.intValue = script[pos + 1];
            out.encodedSize = 2;
            pos += 2;
            return true;

        case 0x1D: // EX_IntConst
        {
            if (pos + 5 > script.size())
                return false;
            int32_t v = 0;
            std::memcpy(&v, script.data() + pos + 1, 4);
            out.intValue = v;
            out.encodedSize = 5;
            pos += 5;
            return true;
        }

        case 0x1E: // EX_FloatConst
            if (pos + 5 > script.size())
                return false;
            std::memcpy(&out.floatValue, script.data() + pos + 1, 4);
            out.encodedSize = 5;
            pos += 5;
            return true;

        case 0x20: // EX_ObjectConst -> UObject*
        {
            if (pos + 9 > script.size())
                return false;

            std::memcpy(
                &out.objectPtr,
                script.data() + pos + 1,
                8);

            BobFoodTraceResolveUObjectShortName(
                m, g,
                out.objectPtr,
                out.objectName);

            out.encodedSize = 9;
            pos += 9;
            return true;
        }

        case 0x21: // EX_NameConst -> case-preserving FName payload
        {
            if (pos + 13 > script.size())
                return false;

            BobFoodTraceResolveFNameInline(
                m, g,
                script.data() + pos + 1,
                script.size() - (pos + 1),
                out.nameValue);

            out.encodedSize = 13;
            pos += 13;
            return true;
        }

        case 0x42: // EX_StructMemberContext
        {
            // Encoding used by this UE build:
            //   0x42
            //   FProperty* member
            //   context expression
            //
            // The two FoodByType Map_Add sites seen in AH7 use a direct
            // local-variable expression as that context.
            if (pos + 10 > script.size())
                return false;

            const size_t start = pos;
            std::memcpy(&out.memberFieldPtr, script.data() + pos + 1, 8);
            BobFoodTraceResolveFieldName(
                m, g,
                out.memberFieldPtr,
                out.memberFieldName,
                out.memberFieldNameOffset);

            pos += 9;
            if (pos >= script.size())
                return false;

            out.contextToken = script[pos];

            if (out.contextToken == 0x00 ||
                out.contextToken == 0x01 ||
                out.contextToken == 0x48) {
                if (pos + 9 > script.size())
                    return false;

                std::memcpy(
                    &out.contextFieldPtr,
                    script.data() + pos + 1,
                    8);

                BobFoodTraceResolveFieldName(
                    m, g,
                    out.contextFieldPtr,
                    out.contextFieldName,
                    out.contextFieldNameOffset);

                pos += 9;
                out.encodedSize = pos - start;
                return true;
            }

            if (out.contextToken == 0x17) { // EX_Self
                ++pos;
                out.encodedSize = pos - start;
                return true;
            }

            return false;
        }

        default:
            // AH4 deliberately does not attempt to recursively parse arbitrary
            // expressions yet. The current Food_Regenerated call observed by
            // AH3 uses only simple tokens for all nine SDK parameters.
            return false;
    }
}

static void BobFoodTraceReportValueFieldRefs(
    std::ostringstream& report,
    const std::vector<uint8_t>& script,
    uint64_t fieldPtr,
    size_t callOffset)
{
    if (!fieldPtr || script.size() < 8)
        return;

    uint8_t ptrBytes[8] = {};
    std::memcpy(ptrBytes, &fieldPtr, 8);

    struct Ref {
        size_t ptrOffset = 0;
        size_t exprOffset = 0;
        uint8_t preceding = 0xFF;
        ptrdiff_t delta = 0;
    };
    std::vector<Ref> refs;

    for (size_t p = 0; p + 8 <= script.size(); ++p) {
        if (std::memcmp(script.data() + p, ptrBytes, 8) != 0)
            continue;

        Ref r;
        r.ptrOffset = p;
        r.exprOffset = p > 0 ? p - 1 : p;
        r.preceding = p > 0 ? script[p - 1] : 0xFF;
        r.delta = (ptrdiff_t)r.exprOffset - (ptrdiff_t)callOffset;
        refs.push_back(r);
    }

    std::sort(refs.begin(), refs.end(),
        [callOffset](const Ref& a, const Ref& b) {
            const long long da =
                std::llabs((long long)a.exprOffset - (long long)callOffset);
            const long long db =
                std::llabs((long long)b.exprOffset - (long long)callOffset);
            return da < db;
        });

    report << "      Value-field exact pointer references: "
           << refs.size() << "\n";

    const size_t limit = std::min<size_t>(refs.size(), 16u);
    for (size_t i = 0; i < limit; ++i) {
        const Ref& r = refs[i];
        report << "        expr +0x" << std::hex << r.exprOffset
               << "  ptr +0x" << r.ptrOffset << std::dec
               << "  token=0x" << std::hex
               << (unsigned)r.preceding << std::dec
               << " (" << BobFoodTraceTokenName(r.preceding) << ")"
               << "  delta=" << r.delta << " bytes\n";

        const size_t wb = r.exprOffset > 48 ? r.exprOffset - 48 : 0;
        const size_t we = std::min(script.size(), r.exprOffset + 96);
        report << BobFoodTraceHexWindow(script, wb, we);
    }

    // Direct assignment signatures where the FProperty* itself immediately
    // follows an assignment token. These are particularly valuable because
    // they can reveal where the local Value variable is populated.
    int directLets = 0;
    for (size_t p = 1; p + 8 <= script.size(); ++p) {
        if (std::memcmp(script.data() + p, ptrBytes, 8) != 0)
            continue;
        const uint8_t tok = script[p - 1];
        if (tok != 0x0F && tok != 0x64)
            continue;

        ++directLets;
        const size_t expr = p - 1;
        report << "      ASSIGNMENT CANDIDATE +0x"
               << std::hex << expr << std::dec
               << "  " << BobFoodTraceTokenName(tok)
               << "  delta="
               << ((ptrdiff_t)expr - (ptrdiff_t)callOffset)
               << " bytes\n";
        const size_t wb = expr > 80 ? expr - 80 : 0;
        const size_t we = std::min(script.size(), expr + 192);
        report << BobFoodTraceHexWindow(script, wb, we);
    }

    if (directLets == 0) {
        report << "      Direct EX_Let / persistent-frame assignment candidates: none\n";
    }
}


static const char* BobFoodTraceCallTokenName(uint8_t tok)
{
    switch (tok) {
        case 0x1C: return "EX_FinalFunction";
        case 0x46: return "EX_LocalFinalFunction";
        case 0x68: return "EX_CallMath";
        default:   return "EX_Call";
    }
}

static void BobFoodTraceReportArgDetails(
    std::ostringstream& report,
    const BobFoodTraceArg& a)
{
    if (a.fieldPtr) {
        report << " field=0x" << std::hex << a.fieldPtr << std::dec;
        if (!a.fieldName.empty())
            report << " name=\"" << a.fieldName << "\"";
        else
            report << " name=<unresolved>";
        return;
    }

    if (a.token == 0x42) {
        report << " member=0x" << std::hex
               << a.memberFieldPtr << std::dec;
        if (!a.memberFieldName.empty())
            report << " memberName=\"" << a.memberFieldName << "\"";
        else
            report << " memberName=<unresolved>";

        report << " contextToken=0x" << std::hex
               << (unsigned)a.contextToken << std::dec
               << " (" << BobFoodTraceTokenName(a.contextToken) << ")";

        if (a.contextFieldPtr) {
            report << " contextField=0x" << std::hex
                   << a.contextFieldPtr << std::dec;
            if (!a.contextFieldName.empty())
                report << " contextName=\""
                       << a.contextFieldName << "\"";
            else
                report << " contextName=<unresolved>";
        }
        return;
    }

    if (a.token == 0x24 || a.token == 0x1D) {
        report << " value=" << a.intValue;
        return;
    }

    if (a.token == 0x1E) {
        report << " value=" << a.floatValue;
        return;
    }

    if (a.token == 0x20) {
        report << " object=0x" << std::hex
               << a.objectPtr << std::dec;
        if (!a.objectName.empty())
            report << " objectName=\"" << a.objectName << "\"";
        return;
    }

    if (a.token == 0x21) {
        if (!a.nameValue.empty())
            report << " nameValue=\"" << a.nameValue << "\"";
        else
            report << " nameValue=<unresolved>";
        return;
    }
}




